vice_instance_manifest_parser\\\",\\n        \\\"//score/mw/com/test/common_test_resources:skeleton_container\\\",\\n        \\\"@score_baselibs//score/result\\\",\\n    ],\\n)\\n\\npkg_application(\\n    name = \\\"main_api_idempotency-pkg\\\",\\n    app_name = \\\"ApiIdempotencyApp\\\",\\n    bin = [\\\":main_api_idempotency\\\"],\\n    etc = [\\n        \\\"config/logging.json\\\",\\n        \\\"config/mw_com_config.json\\\",\\n    ],\\n    visibility = [\\n        \\\"//score/mw/com/test/api_idempotency:__subpackages__\\\",\\n    ],\\n)\\n\", \"score/mw/com/test/api_idempotency/integration_test/api_idempotency_test.py\": \"# *******************************************************************************\\n# Copyright (c) 2026 Contributors to the Eclipse Foundation\\n#\\n# See the NOTICE file(s) distributed with this work for additional\\n# information regarding copyright ownership.\\n#\\n# This program and the accompanying materials are made available under the\\n# terms of the Apache License Version 2.0 which is available at\\n# https://www.apache.org/licenses/LICENSE-2.0\\n#\\n# SPDX-License-Identifier: Apache-2.0\\n# *******************************************************************************\\n\\n\\ndef api_idempotency_app(target, **kwargs):\\n    args = [\\\"--service_instance_manifest\\\", \\\"./etc/mw_com_config.json\\\"]\\n    return target.wrap_exec(\\n        \\\"bin/main_api_idempotency\\\",\\n        args,\\n        cwd=\\\"/opt/ApiIdempotencyApp\\\",\\n        wait_on_exit=True,\\n        **kwargs,\\n    )\\n\\n\\ndef test_api_idempotency(target):\\n    \\\"\\\"\\\"Integration test for idempotent public API calls.\\n\\n    The test covers OfferService, StopOfferService, StartFindService, Subscribe\\n    and Unsubscribe. It verifies duplicate offers keep the service discoverable,\\n    repeated stops remove discovery, repeated StartFindService registrations\\n    discover the service and are cleaned up, duplicate Subscribe with the same\\n    sample limit preserves subscription and sample reception, and repeated\\n    Unsubscribe leaves the event unsubscribed so re-subscription still works.\\n    \\\"\\\"\\\"\\n    with api_idempotency_app(target):\\n        pass\\n\", \"score/mw/com/test/api_idempotency/integration_test/BUILD\": \"# *******************************************************************************\\n# Copyright (c) 2026 Contributors to the Eclipse Foundation\\n#\\n# See the NOTICE file(s) distributed with this work for additional\\n# information regarding copyright ownership.\\n#\\n# This program and the accompanying materials are made available under the\\n# terms of the Apache License Version 2.0 which is available at\\n# https://www.apache.org/licenses/LICENSE-2.0\\n#\\n# SPDX-License-Identifier: Apache-2.0\\n# *******************************************************************************\\n\\nload(\\\"@rules_pkg//pkg:mappings.bzl\\\", \\\"pkg_filegroup\\\")\\nload(\\\"//quality/integration_testing:integration_testing.bzl\\\", \\\"integration_test\\\")\\n\\npkg_filegroup(\\n    name = \\\"filesystem\\\",\\n    srcs = [\\n        \\\"//score/mw/com/test/api_idempotency:main_api_idempotency-pkg\\\",\\n    ],\\n)\\n\\nintegration_test(\\n    name = \\\"api_idempotency_test\\\",\\n    timeout = \\\"moderate\\\",\\n    srcs = [\\\"api_idempotency_test.py\\\"],\\n    filesystem = \\\":filesystem\\\",\\n)\\n\", \"score/mw/com/test/api_idempotency/config/mw_com_config.json\": \"{\\n  \\\"serviceTypes\\\": [\\n    {\\n      \\\"serviceTypeName\\\": \\\"/score/mw/com/test/api_idempotency/api_idempotency_type\\\",\\n      \\\"version\\\": {\\n        \\\"major\\\": 1,\\n        \\\"minor\\\": 0\\n      },\\n      \\\"bindings\\\": [\\n        {\\n          \\\"binding\\\": \\\"SHM\\\",\\n          \\\"serviceId\\\": 3431,\\n          \\\"events\\\": [\\n            {\\n              \\\"eventName\\\": \\\"test_event\\\",\\n              \\\"eventId\\\": 1\\n            }\\n          ]\\n        }\\n      ]\\n    }\\n  ],\\n  \\\"serviceInstances\\\": [\\n    {\\n      \\\"instanceSpecifier\\\": \\\"/score/mw/com/test/api_idempotency/api_idempotency_instance\\\",\\n      \\\"serviceTypeName\\\": \\\"/score/mw/com/test/api_idempotency/api_idempotency_type\\\",\\n      \\\"version\\\": {\\n        \\\"major\\\": 1,\\n        \\\"minor\\\": 0\\n      },\\n      \\\"instances\\\": [\\n        {\\n          \\\"instanceId\\\": 1026,\\n          \\\"asil-level\\\": \\\"QM\\\",\\n          \\\"binding\\\": \\\"SHM\\\",\\n          \\\"events\\\": [\\n            {\\n              \\\"eventName\\\": \\\"test_event\\\",\\n              \\\"maxSamples\\\": 10,\\n              \\\"maxSubscribers\\\": 3\\n            }\\n          ]\\n        }\\n      ]\\n    }\\n  ]\\n}\\n\", \"score/mw/com/test/api_idempotency/config/logging.json\": \"{\\n  \\\"appId\\\": \\\"APIID\\\",\\n  \\\"appDesc\\\": \\\"api_idempotency\\\",\\n  \\\"logLevel\\\": \\\"kDebug\\\",\\n  \\\"logLevelThresholdConsole\\\": \\\"kDebug\\\",\\n  \\\"logMode\\\": \\\"kRemote|kConsole\\\"\\n}\\n\"}, \"pinned_native_context\": \"\\n\\nFILE CONTRIBUTING.md\\n# Contributing\\n\\n- Thank you for your interest in contributing to the Communication Module of the Eclipse SCORE project!\\n- This guide will walk you through the necessary steps to get started with development, adhere to our standards, and successfully submit your contributions.\\n\\n## Eclipse Contributor Agreement (ECA)\\n\\nBefore making any contributions, **you must sign the Eclipse Contributor Agreement (ECA)**. This is a mandatory requirement for all contributors to Eclipse projects.\\n\\nSign the ECA here: https://www.eclipse.org/legal/ECA.php\\n\\nPull requests from contributors who have not signed the ECA **will not be accepted**.\\n\\n## Contribution Workflow\\n\\nTo ensure a smooth contribution process, please follow the steps below:\\n\\n1. **Fork** the repository to your GitHub account.\\n2. **Create a feature branch** from your fork:\\n   ```bash\\n   git checkout -b feature/your-feature-name\\n   ```\\n3. **Write clean and modular code**, adhering to:\\n   - **C++17 standard**\\n   - **Google C++ Style Guide**\\n4. **Add tests** for any new functionality.\\n5. **Ensure all tests pass** before submitting:\\n   ```bash\\n   bazel test //...\\n   ```\\n6. **Open a Pull Request** from your feature branch to the `main` branch of the upstream repository.\\n   - Provide a clear title and description of your changes.\\n   - Reference any related issues.\\n\\n## Development Setup\\n\\n### General Prerequisites\\n\\n- Bazel (Instructions for installing here: https://bazel.build/install)\\n- Docker (Instructions for installing here: https://docs.docker.com/engine/install/)\\n  - Note. Running Docker in rootless mode is not yet officially supported but may work. See https://docs.docker.com/engine/security/rootless/ for more information.\\n\\n### OS-specific Prerequisites\\n\\nWe strive to be independent of the host platform via bazel sandboxing.\\nSome host platforms come with limitations that bazel cannot sandbox sufficiently.\\nFor these platforms we collect instructions below.\\n\\nPlease be aware, that while we officially support Ubuntu 24.04 as the host platform that we also test in our CI.\\nWhile other platforms generally should work, we can give no such guarantee.\\nShould you face issues with your host platform, feel free to raise an issue or discussion where we will try to support.\\n\\n#### Ubuntu 24.04 and newer\\n\\nStarting with Ubuntu 24.04 the security framework apparmor was introduced.\\nThe standard configuration of apparmor prohibits unprivileged user namespaces.\\nThis interferes with the bazel sandboxing mechanism and inhibits the linux-sandbox.\\nBazel falls back to a less powerful sandboxing mechanism that is insufficient for our project.\\nThis affects many bazel tests and potentially any bazel runnables.\\n\\nTo work around this issue, you can run a bash script, which you can get by cloning the cicd-actions repository\\n\\n```\\ngit clone --depth=1 https://github.com/eclipse-score/cicd-actions\\n```\\n\\nafter which you can run\\n\\n```bash\\nbash <path to cicd-actions repository>/unblock_user_namespace_for_linux_sandbox/action_callable.sh\\n```\\n\\nNote. To take this into effect force, a bazel restart by shutting it down 1st\\n\\n```bash\\nbazel shutdown\\n```\\n\\nThese steps must be rerun whenever the bazel version is updated.\\n\\n### Build Instructions\\n\\nTo build and test the Communication Module, follow the steps below from the project root:\\n\\n```bash\\n# Build all targets\\nbazel build //...\\n\\n# Run all tests\\nbazel test //...\\n```\\n\\n### Optional: Configure a local Ubuntu snapshot mirror\\n\\nThe Ubuntu snapshot mirrors are sometimes unreliable. See: https://answers.launchpad.net/launchpad/+question/824541\\n\\nIf you have access to a more reliable Ubuntu snapshot mirror, you can make Bazel try it first while keeping\\nthe public `snapshot.ubuntu.com` URL as fallback.\\n\\nAn example for such a snapshot mirror service is https://stablebuild.com\\n\\n1. Create a local downloader config at `user.downloader_config` (this file is ignored by git).\\n   Replace the `<private-mirror-tag>` with the tag provided by the StableBuild API\\n\\n```text\\nrewrite snapshot.ubuntu.com/ubuntu/[^/]*/(.*) <private-mirror-tag>.debmirror.stablebuild.com/2026-04-01T10:40:01Z/archive.ubuntu.com/ubuntu/$1\\nrewrite snapshot.ubuntu.com/ubuntu/[^/]*/(.*) <private-mirror-tag>.debmirror.stablebuild.com/2026-04-01T10:40:01Z/ports.ubuntu.com/$1\\nrewrite snapshot.ubuntu.com/ubuntu/(.*) snapshot.ubuntu.com/ubuntu/$1\\n```\\n\\n2. Point Bazel to this local config in `user.bazelrc` (also ignored by git):\\n\\n```text\\ncommon --downloader_config=user.downloader_config\\n```\\n\\n3. Restart the Bazel server to reload the downloader config\\n\\n```shell\\nbazel shutdown\\n```\\n\\n### Linting Instructions\\n\\nFor Linting the Code following solutions are available:\\n\\nCopyright Checker:\\n```bash\\n# Check Sources\\nbazel run //:copyright.check\\n\\n# Fix Sources\\nbazel run //:copyright.fix\\n```\\n\\nC++ and Bazel files formatter:\\n```bash\\n# Check Sources\\nbazel run //:format.check\\n\\n# Fix Sources\\nbazel run //:format\\n```\\n\\n### Testing Instructions\\n\\nThe Communication Module includes extensive tests. Use the following commands:\\n\\n#### Run All Tests\\n```bash\\nbazel test //...\\n```\\n\\n#### Run Specific Test Suites\\n```bash\\nbazel test //score/mw/com/impl:all\\nbazel test //score/mw/com/message_passing:all\\n```\\n\\n#### Test Categories\\n- **Unit Tests**: Component-level testing\\n- **Integration Tests**: Cross-component interactions\\n- **Performance Tests**: Latency and throughput benchmarks\\n- **Safety Tests**: ASIL-B compliance verification\\n\\n## Additional Resources\\n\\nFor project details, documentation, and support resources, please refer to the main [README.md](README.md).\\nFor the release process, see [RELEASING.md](RELEASING.md).\\n\\n---\\n\\n## How to Document\\n\\nThis section explains how to document C++ code so it appears in the generated API documentation.\\n\\n> API documentation is generated using Doxygen and integrated via Breathe.\\n> Due to Sphinx version < 9.x limitations with complex C++ templates, use specific class\\n> and function directives rather than namespace-level documentation.\\n\\n### Automatic API Documentation with @api Tag\\n\\nThe project includes an automated RST generation utility that extracts items\\ntagged with `@api` in Doxygen comments and generates categorized documentation.\\n\\nAdd the `@api` tag to any Doxygen comment block to include it in the generated API documentation:\\n\\n```cpp\\n/**\\n * @brief Connection handler for client communication\\n * @api\\n */\\nclass ClientConnection {\\n    // ...\\n};\\n\\n/**\\n * @brief Initialize the communication system\\n * @return true if successful\\n * @api\\n */\\nbool initialize();\\n```\\n\\nThe utility automatically creates:\\n\\n- **API Index** — overview of all tagged items\\n- **Namespace Reference** — namespaces containing `@api` items\\n- **Class Reference** — classes and structs with `@api` tag\\n- **Member Reference** — functions and methods with `@api` tag\\n\\nBuild integration:\\n\\n```starlark\\ngenerate_api_rst(\\n    name = \\\"generate_api_rst\\\",\\n    doxygen_xml = \\\"//path/to:doxygen_target\\\",\\n    output_dir = \\\"generated\\\",\\n    project_name = \\\"mw::com\\\",\\n)\\n```\\n\\nThe generated RST files are automatically included in the Sphinx documentation\\nunder the \\\"Generated API Documentation\\\" section.\\n\\n### Using Breathe Directives\\n\\nTo document specific classes or functions, use these Breathe directives in RST files:\\n\\n**Document a specific class:**\\n\\n```rst\\n.. doxygenclass:: score::message_passing::detail::ClientConnection\\n    :members:\\n    :protected-members:\\n    :undoc-members:\\n```\\n\\n**Document a specific function:**\\n\\n```rst\\n.. doxygenfunction:: score::mw::com::functionName\\n```\\n\\n**Document a struct:**\\n\\n```rst\\n.. doxygenstruct:: score::mw::com::ConfigStruct\\n    :members:\\n```\\n\\n### Further Resources\\n\\n- Browse the Doxygen-generated HTML at `bazel-bin/score/mw/com/design/doxygen_build/html/index.html`\\n- Review header files in `score/mw/com/` for inline documentation\\n- Check the design documentation at `score/mw/com/design/`\\n\\n**Thank you for contributing to the Eclipse SCORE Communication Module!**\\n\\n\\nFILE score/mw/com/impl/proxy_base.h\\n/********************************************************************************\\n * Copyright (c) 2025 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License Version 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n ********************************************************************************/\\n#ifndef SCORE_MW_COM_IMPL_PROXY_BASE_H\\n#define SCORE_MW_COM_IMPL_PROXY_BASE_H\\n\\n#include \\\"score/mw/com/impl/find_service_handle.h\\\"\\n#include \\\"score/mw/com/impl/find_service_handler.h\\\"\\n#include \\\"score/mw/com/impl/handle_type.h\\\"\\n#include \\\"score/mw/com/impl/instance_identifier.h\\\"\\n#include \\\"score/mw/com/impl/instance_specifier.h\\\"\\n#include \\\"score/mw/com/impl/proxy_binding.h\\\"\\n#include \\\"score/mw/com/impl/reference_to_moveable.h\\\"\\n\\n#include \\\"score/result/result.h\\\"\\n\\n#include <score/span.hpp>\\n\\n#include <memory>\\n#include <string_view>\\n\\nnamespace score::mw::com::impl\\n{\\n\\nclass ProxyEventBase;\\nclass ProxyFieldBase;\\nclass ProxyMethodBase;\\n\\n/// \\\\brief Base class for all binding-unspecific proxies that are generated from the IDL.\\nclass ProxyBase\\n{\\n\\n    // Suppress \\\"AUTOSAR C++14 A11-3-1\\\", The rule states: \\\"Friend declarations shall not be used\\\".\\n    // Design decision. This class provides a view to the private members of this class.\\n    // coverity[autosar_cpp14_a11_3_1_violation]\\n    friend class ProxyBaseView;\\n\\n  public:\\n    /// \\\\brief Identifier for a specific instance of a specific service\\n    using HandleType = ::score::mw::com::impl::HandleType;\\n\\n    /// \\\\brief Creation of ProxyBase which should be called by parent class (generated Proxy or GenericProxy)\\n    ProxyBase(std::unique_ptr<ProxyBinding> proxy_binding, HandleType handle);\\n\\n    virtual ~ProxyBase() = default;\\n\\n    /// \\\\brief A Proxy shall not be copyable\\n    /// \\\\requirement SWS_CM_00136\\n    ProxyBase(const ProxyBase&) = delete;\\n    ProxyBase& operator=(const ProxyBase&) = delete;\\n\\n    /**\\n     * \\\\api\\n     * \\\\brief Tries to find a service that matches the given specifier synchronously.\\n     * \\\\details Does a synchronous one-shot lookup/find, which service instance(s) matching the specifier are there.\\n     * \\\\param specifier The instance specifier of the service.\\n     * \\\\return A result which on success contains a list of found handles that can be used to create a proxy. On\\n     *         failure, returns an error code.\\n     * \\\\requirement SWS_CM_00622\\n     */\\n    static Result<ServiceHandleContainer<HandleType>> FindService(InstanceSpecifier specifier);\\n\\n    /**\\n     * \\\\api\\n     * \\\\brief Tries to find a service that matches the given instance identifier synchronously.\\n     * \\\\details Does a synchronous one-shot lookup/find, which service instance(s) matching the specifier are there.\\n     * \\\\param instance_identifier The instance_identifier of the service.\\n     * \\\\return A result which on success contains a list of found handles that can be used to create a proxy. On\\n     *         failure, returns an error code.\\n     */\\n    static Result<ServiceHandleContainer<HandleType>> FindService(InstanceIdentifier instance_identifier);\\n\\n    /**\\n     * \\\\api\\n     * \\\\brief Starts asynchronous service discovery that matches the given instance identifier.\\n     * \\\\details Initiates a continuous service discovery operation. The provided handler will be called whenever\\n     *          matching service instances become available or unavailable.\\n     * \\\\param handler The callback handler to be invoked when service availability changes.\\n     * \\\\param instance_identifier The instance identifier of the service to find.\\n     * \\\\return A result which on success contains a handle to control the find operation. On failure, returns an\\n     *         error code.\\n     */\\n    static Result<FindServiceHandle> StartFindService(FindServiceHandler<HandleType> handler,\\n                                                      InstanceIdentifier instance_identifier);\\n\\n    /**\\n     * \\\\api\\n     * \\\\brief Starts asynchronous service discovery that matches the given instance specifier.\\n     * \\\\details Initiates a continuous service discovery operation. The provided handler will be called whenever\\n     *          matching service instances become available or unavailable.\\n     * \\\\param handler The callback handler to be invoked when service availability changes.\\n     * \\\\param instance_specifier The instance specifier of the service to find.\\n     * \\\\return A result which on success contains a handle to control the find operation. On failure, returns an\\n     *         error code.\\n     */\\n    static Result<FindServiceHandle> StartFindService(FindServiceHandler<HandleType> handler,\\n                                                      InstanceSpecifier instance_specifier);\\n\\n    /**\\n     * \\\\api\\n     * \\\\brief Stops an ongoing asynchronous service discovery operation.\\n     * \\\\details Terminates the service discovery initiated by StartFindService. After this call, the associated\\n     *          handler will no longer be invoked.\\n     * \\\\param handle The handle returned by StartFindService identifying the find operation to stop.\\n     * \\\\return A result indicating success or failure of stopping the find operation.\\n     */\\n    static score::Result<void> StopFindService(const FindServiceHandle handle);\\n\\n    /**\\n     * \\\\api\\n     * \\\\brief Returns the handle that was used to instantiate this proxy.\\n     * \\\\return Handle identifying the service that this proxy is connected to.\\n     */\\n    const HandleType& GetHandle() const& noexcept;\\n\\n  protected:\\n    using ProxyEvents =\\n        std::map<std::string_view, std::reference_wrapper<ReferenceToMoveable<ProxyEventBase>::Reference>>;\\n    using ProxyFields =\\n        std::map<std::string_view, std::reference_wrapper<ReferenceToMoveable<ProxyFieldBase>::Reference>>;\\n    using ProxyMethods =\\n        std::map<std::string_view, std::reference_wrapper<ReferenceToMoveable<ProxyMethodBase>::Reference>>;\\n\\n    /// \\\\brief A Proxy shall be movable\\n    /// \\\\requirement SWS_CM_00137\\n    ProxyBase(ProxyBase&& other) noexcept = default;\\n    ProxyBase& operator=(ProxyBase&& other) noexcept = default;\\n\\n    /// \\\\brief Deinitialize all events and fields and tears down binding-level state.\\n    ///  Must only be invoked from the wrapper class destructor (ProxyWrapperClass / GenericProxy).\\n    ///      Calling this from user code leaves the binding in a torn-down state mid-life.\\n    void Deinitialize();\\n\\n    bool AreBindingsValid() const noexcept;\\n\\n    /// \\\\brief Dispatches to the binding for any binding specific setup and then initializes all method InArgs and\\n    /// Return values.\\n    ///\\n    /// The initialization of the InArgs and Return values is done on the binding independent level since the binding\\n    /// level is type erased. The values are initialized once on startup and then reused (i.e. we never re-initialize\\n    /// the values when calling a method).\\n    ///\\n    /// \\\\param additional_shm_size_bytes Additional shared memory size in bytes to be allocated for methods in addition\\n    /// to the size calculated for the size of the method in args and return values. This is a temporary workaround\\n    /// added to allow using types which dynamically allocate memory once at runtime. This is not currently public and\\n    /// should not be used by user applications. (SWP-269486)\\n    Result<void> SetupMethods(std::size_t additional_shm_size_bytes);\\n\\n    // Suppress \\\"AUTOSAR C++14 M11-0-1\\\" rule findings. This rule states: \\\"Member data in non-POD class types shall\\n    // be private.\\\". We need these data elements to exchange this information between the ProxyBase and the\\n    // GenericProxy. There are no class invariants to maintain which could be violated by directly accessing these\\n    // member variables.\\n    // coverity[autosar_cpp14_m11_0_1_violation]\\n    std::unique_ptr<ProxyBinding> proxy_binding_;\\n    // coverity[autosar_cpp14_m11_0_1_violation]\\n    HandleType handle_;\\n\\n    ProxyEvents events_;\\n    ProxyFields fields_;\\n    ProxyMethods methods_;\\n};\\n\\nclass ProxyBaseView final\\n{\\n  public:\\n    /// \\\\brief Create a view on the ProxyBase instance to allow for additional methods on the ProxyBase.\\n    ///\\n    /// \\\\param proxy_base The ProxyBase to create the view on.\\n    explicit ProxyBaseView(ProxyBase& proxy_base) noexcept;\\n\\n    /// \\\\brief Return a reference to the underlying implementation provided by the binding.\\n    ProxyBinding& GetBinding() noexcept;\\n\\n    const HandleType& GetAssociatedHandleType() const& noexcept;\\n\\n    void RegisterEvent(const std::string_view event_name, ReferenceToMoveable<ProxyEventBase>::Reference& event);\\n\\n    void RegisterField(const std::string_view field_name, ReferenceToMoveable<ProxyFieldBase>::Reference& field);\\n\\n    void RegisterMethod(const std::string_view method_name, ReferenceToMoveable<ProxyMethodBase>::Reference& method);\\n\\n    bool AreBindingsValid() const;\\n\\n  private:\\n    ProxyBase& proxy_base_;\\n};\\n\\n}  // namespace score::mw::com::impl\\n\\n#endif  // SCORE_MW_COM_IMPL_PROXY_BASE_H\\n\\n\\nFILE score/mw/com/impl/proxy_event.h\\n/********************************************************************************\\n * Copyright (c) 2025 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License Version 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n ********************************************************************************/\\n#ifndef SCORE_MW_COM_IMPL_PROXYEVENT_H\\n#define SCORE_MW_COM_IMPL_PROXYEVENT_H\\n\\n#include \\\"score/mw/com/impl/instance_identifier.h\\\"\\n#include \\\"score/mw/com/impl/plumbing/proxy_event_binding_factory.h\\\"\\n#include \\\"score/mw/com/impl/plumbing/sample_ptr.h\\\"\\n#include \\\"score/mw/com/impl/proxy_base.h\\\"\\n#include \\\"score/mw/com/impl/proxy_event_base.h\\\"\\n#include \\\"score/mw/com/impl/proxy_event_binding.h\\\"\\n#include \\\"score/mw/com/impl/runtime.h\\\"\\n#include \\\"score/mw/com/impl/tracing/proxy_event_tracing.h\\\"\\n\\n#include \\\"score/mw/com/impl/mocking/i_proxy_event.h\\\"\\n\\n#include \\\"score/mw/log/logging.h\\\"\\n#include \\\"score/result/result.h\\\"\\n\\n#include <score/assert.hpp>\\n\\n#include <cstddef>\\n#include <memory>\\n#include <string_view>\\n#include <utility>\\n\\nnamespace score::mw::com::impl\\n{\\n\\n// False Positive: this is a normal forward declaration.\\n// Which is used to avoid cyclic dependency with proxy_field.h\\n// coverity[autosar_cpp14_m3_2_3_violation]\\ntemplate <typename, typename...>\\nclass ProxyField;\\n\\n/// \\\\brief This is the user-visible class of an event that is part of a proxy. It contains ProxyEvent functionality that\\n/// requires knowledge of the SampleType. All type agnostic functionality is stored in the base class, ProxyEventBase.\\n///\\n/// The class itself is a concrete type. However, it delegates all actions to an implementation\\n/// that is provided by the binding the proxy is operating on.\\n///\\n/// \\\\tparam SampleDataType Type of data that is transferred by the event.\\ntemplate <typename SampleDataType>\\nclass ProxyEvent final : public ProxyEventBase\\n{\\n    template <typename T>\\n    // Design decission: This friend class provides a view on the internals of ProxyEvent.\\n    // This enables us to hide unncecessary internals from the enduser.\\n    // coverity[autosar_cpp14_a11_3_1_violation]\\n    friend class ProxyEventView;\\n\\n    // Design decission: ProxyField uses composition pattern to reuse code from ProxyEvent. These two classes also have\\n    // shared private APIs which necessitates the use of the friend keyword.\\n    // coverity[autosar_cpp14_a11_3_1_violation]\\n    template <typename, typename...>\\n    friend class ProxyFieldImpl;\\n\\n    // Empty struct that is used to make the second constructor only accessible to ProxyField (as it is a friend).\\n    struct FieldOnlyConstructorEnabler\\n    {\\n    };\\n\\n  public:\\n    using SampleType = SampleDataType;\\n\\n    /// Constructor which is dispatched to by the other public constructors.\\n    ///\\n    /// Instantiates the base class and members of ProxyEvent. Should only be called directly in tests.\\n    ///\\n    /// \\\\param proxy_binding The binding that shall be associated with this proxy.\\n    ProxyEvent(const std::string_view event_name, std::unique_ptr<ProxyEventBinding> proxy_event_binding);\\n\\n    /// \\\\brief Constructor that allows to set the binding directly.\\n    ///\\n    /// This is used by ProxyField to pass in a ProxyEventBinding created using the ProxyFieldBindingFactory.\\n    ///\\n    /// \\\\param proxy_binding The binding that shall be associated with this proxy.\\n    ProxyEvent(ProxyBase& base,\\n               const std::string_view event_name,\\n               Result<std::unique_ptr<ProxyEventBinding>> proxy_event_binding,\\n               FieldOnlyConstructorEnabler);\\n\\n    /// \\\\brief Constructs a ProxyEvent by querying the base proxie's ProxyBinding for the respective ProxyEventBinding.\\n    ///\\n    /// \\\\param base Proxy that contains this event\\n    /// \\\\param event_name Event name of the event, taken from the AUTOSAR model\\n    /// \\\\todo Remove unneeded parameter once we get these information from the configuration\\n    ProxyEvent(ProxyBase& base, const std::string_view event_name);\\n\\n    /// \\\\brief A ProxyEvent shall not be copyable\\n    ProxyEvent(const ProxyEvent&) = delete;\\n    ProxyEvent& operator=(const ProxyEvent&) & = delete;\\n\\n    /// \\\\brief A ProxyEvent shall be movable\\n    ProxyEvent(ProxyEvent&& other) noexcept = default;\\n    ProxyEvent& operator=(ProxyEvent&& other) noexcept = default;\\n\\n    ~ProxyEvent() override = default;\\n\\n    /**\\n     * \\\\api\\n     * \\\\brief Receive pending data from the event.\\n     * \\\\details The user needs to provide a callable that fulfills the following signature:\\n     *          void F(SamplePtr<const SampleType>) noexcept. This callback will be called for each sample\\n     *          that is available at the time of the call. Notice that the number of callback calls cannot\\n     *          exceed std::min(GetFreeSampleCount(), max_num_samples) times.\\n     * \\\\tparam F Callable with the signature void(SamplePtr<const SampleType>) noexcept\\n     * \\\\param receiver Callable with the appropriate signature. GetNewSamples will take ownership\\n     *                 of this callable.\\n     * \\\\param max_num_samples Maximum number of samples to return via the given callable.\\n     * \\\\return Number of samples that were handed over to the callable or an error.\\n     */\\n    template <typename F>\\n    Result<std::size_t> GetNewSamples(F&& receiver, std::size_t max_num_samples) noexcept;\\n\\n    void InjectMock(IProxyEvent<SampleType>& proxy_event_mock)\\n    {\\n        proxy_event_mock_ = &proxy_event_mock;\\n        ProxyEventBase::InjectMock(proxy_event_mock);\\n    }\\n\\n  private:\\n    IProxyEvent<SampleType>* proxy_event_mock_;\\n\\n    /// \\\\brief Indicates whether this event is a field event (i.e. owned by a ProxyField, which is a composite of\\n    /// method/event) or not.\\n};\\n\\ntemplate <typename SampleType>\\nProxyEvent<SampleType>::ProxyEvent(const std::string_view event_name,\\n                                   std::unique_ptr<ProxyEventBinding> proxy_event_binding)\\n    : ProxyEventBase{event_name, std::move(proxy_event_binding)}, proxy_event_mock_{nullptr}\\n{\\n}\\n\\ntemplate <typename SampleType>\\nProxyEvent<SampleType>::ProxyEvent(ProxyBase& base, const std::string_view event_name)\\n\\n    : ProxyEventBase{event_name,\\n                     ProxyEventBindingFactory<SampleType>::Create(base.GetHandle(),\\n                                                                  ProxyBaseView{base}.GetBinding(),\\n                                                                  event_name,\\n                                                                  ServiceElementType::EVENT)\\n                         .and_then([](std::unique_ptr<ProxyEventBinding> binding) {\\n                             return Result<std::unique_ptr<ProxyEventBinding>>{std::move(binding)};\\n                         })},\\n      proxy_event_mock_{nullptr}\\n{\\n    ProxyBaseView proxy_base_view{base};\\n    proxy_base_view.RegisterEvent(event_name, GetReferenceToMoveable());\\n    if (binding_ != nullptr)\\n    {\\n        const auto& instance_identifier = proxy_base_view.GetAssociatedHandleType().GetInstanceIdentifier();\\n        tracing_data_ = tracing::GenerateProxyTracingStructFromEventConfig(instance_identifier, event_name);\\n    }\\n}\\n\\ntemplate <typename SampleType>\\nProxyEvent<SampleType>::ProxyEvent(ProxyBase& base,\\n                                   const std::string_view event_name,\\n                                   Result<std::unique_ptr<ProxyEventBinding>> proxy_event_binding,\\n                                   FieldOnlyConstructorEnabler)\\n    : ProxyEventBase{event_name, std::move(proxy_event_binding)}, proxy_event_mock_{nullptr}\\n{\\n    // This is the specific ctor that is used by ProxyField for its \\\"dispatch event\\\" composite. Therefore, we do not\\n    // register the event in the ProxyBase's event map, since registration in the correct field map is done by\\n    // ProxyField ctor\\n    if (binding_ != nullptr)\\n    {\\n        ProxyBaseView proxy_base_view{base};\\n        const auto& instance_identifier = proxy_base_view.GetAssociatedHandleType().GetInstanceIdentifier();\\n        tracing_data_ = tracing::GenerateProxyTracingStructFromFieldConfig(instance_identifier, event_name);\\n    }\\n}\\n\\ntemplate <typename SampleType>\\ntemplate <typename F>\\nResult<std::size_t> ProxyEvent<SampleType>::GetNewSamples(F&& receiver, std::size_t max_num_samples) noexcept\\n{\\n    if (proxy_event_mock_ != nullptr)\\n    {\\n        typename IProxyEvent<SampleType>::Callback mock_callback =\\n            [receiver = std::forward<F>(receiver)](SamplePtr<SampleType> sample_ptr) noexcept {\\n                receiver(std::move(sample_ptr));\\n            };\\n        return proxy_event_mock_->GetNewSamples(std::move(mock_callback), max_num_samples);\\n    }\\n\\n    tracing::TraceGetNewSamples(tracing_data_, *binding_);\\n\\n    auto guard_factory = tracker_->Allocate(max_num_samples);\\n\\n    if (guard_factory.GetNumAvailableGuards() == 0U)\\n    {\\n        score::mw::log::LogWarn(\\\"lola\\\")\\n            << \\\"Unable to emit new samples, no free sample slots for this subscription available.\\\";\\n        return MakeUnexpected(ComErrc::kMaxSamplesReached);\\n    }\\n\\n    // The tracing_receiver created here always dispatches to the user provided receiver. Opposed to the user provided\\n    // receiver, which gets a typed sample (SamplePtr<SampleType>), it expects to receive type-erased sample#+\\n    // (SamplePtr<void>). Because this is what the type-erased binding layer provides. Before the tracing_receiver\\n    // dispatches to the user provided receiver, it conditionally traces the received sample and then does a \\\"rebind\\\"\\n    // from the type-erased SamplePtr<void>, the binding provides to the typed SamplePtr<SampleType>, the user provided\\n    // receiver expects.\\n    auto tracing_receiver =\\n        tracing::CreateTracingGetNewSamplesCallback<SampleType, F>(tracing_data_, *binding_, std::forward<F>(receiver));\\n\\n    const auto get_new_samples_result = binding_->GetNewSamples(std::move(tracing_receiver), guard_factory);\\n    if (!get_new_samples_result.has_value())\\n    {\\n        if (get_new_samples_result.error() == ComErrc::kNotSubscribed)\\n        {\\n            return get_new_samples_result;\\n        }\\n        else\\n        {\\n            return MakeUnexpected(ComErrc::kBindingFailure);\\n        }\\n    }\\n    return get_new_samples_result;\\n}\\n\\ntemplate <typename SampleType>\\nclass ProxyEventView\\n{\\n  public:\\n    explicit ProxyEventView(ProxyEvent<SampleType>& proxy_event) : proxy_event_{proxy_event} {}\\n\\n    ProxyEventBinding* GetBinding() const noexcept\\n    {\\n        return proxy_event_.binding_.get();\\n    }\\n\\n  private:\\n    ProxyEvent<SampleType>& proxy_event_;\\n};\\n\\n}  // namespace score::mw::com::impl\\n\\n#endif  // SCORE_MW_COM_IMPL_PROXYEVENT_H\\n\\n\\nFILE score/mw/com/impl/skeleton_base.h\\n/********************************************************************************\\n * Copyright (c) 2025 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License Version 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n ********************************************************************************/\\n#ifndef SCORE_MW_COM_IMPL_SKELETON_BASE_H\\n#define SCORE_MW_COM_IMPL_SKELETON_BASE_H\\n\\n#include \\\"score/mw/com/impl/flag_owner.h\\\"\\n#include \\\"score/mw/com/impl/instance_identifier.h\\\"\\n#include \\\"score/mw/com/impl/instance_specifier.h\\\"\\n#include \\\"score/mw/com/impl/methods/skeleton_method_base.h\\\"\\n#include \\\"score/mw/com/impl/reference_to_moveable.h\\\"\\n#include \\\"score/mw/com/impl/skeleton_binding.h\\\"\\n\\n#include \\\"score/mw/com/impl/mocking/i_skeleton_base.h\\\"\\n\\n#include \\\"score/result/result.h\\\"\\n#include \\\"score/scope_exit/scope_exit.h\\\"\\n\\n#include <score/span.hpp>\\n#include <optional>\\n\\n#include <functional>\\n#include <map>\\n#include <memory>\\n#include <string_view>\\n\\nnamespace score::mw::com::impl\\n{\\n\\nclass SkeletonEventBase;\\nclass SkeletonFieldBase;\\nclass SkeletonMethodBase;\\n\\n/// \\\\brief Parent class for all generated skeletons. Only the generated skeletons will be user facing. But in order to\\n/// reduce code duplication, we encapsulate the common logic in here.\\nclass SkeletonBase\\n{\\n  public:\\n    using SkeletonEvents =\\n        std::map<std::string_view, std::reference_wrapper<ReferenceToMoveable<SkeletonEventBase>::Reference>>;\\n    using SkeletonFields =\\n        std::map<std::string_view, std::reference_wrapper<ReferenceToMoveable<SkeletonFieldBase>::Reference>>;\\n    using SkeletonMethods =\\n        std::map<std::string_view, std::reference_wrapper<ReferenceToMoveable<SkeletonMethodBase>::Reference>>;\\n\\n    /// \\\\brief Creation of service skeleton with provided Skeleton binding\\n    ///\\n    /// \\\\requirement SWS_CM_00130\\n    ///\\n    /// \\\\param skeleton_binding The SkeletonBinding which is created using SkeletonBindingFactory.\\n    /// \\\\param instance_id The instance identifier which uniquely identifies this Skeleton instance.\\n    SkeletonBase(std::unique_ptr<SkeletonBinding> skeleton_binding, InstanceIdentifier instance_id);\\n\\n    virtual ~SkeletonBase() = default;\\n\\n    /// \\\\brief A Skeleton shall not be copyable\\n    /// \\\\requirement SWS_CM_00134\\n    SkeletonBase(const SkeletonBase&) = delete;\\n    SkeletonBase& operator=(const SkeletonBase&) = delete;\\n\\n    /**\\n     * \\\\api\\n     * \\\\brief Offer the respective service to other applications\\n     * \\\\return On failure, returns an error code according to the SW Component Requirements SCR-17434118 and\\n     * SCR-566325.\\n     */\\n    [[nodiscard]] Result<void> OfferService();\\n\\n    /**\\n     * \\\\api\\n     * \\\\brief Stops offering the respective service to other applications\\n     * \\\\requirement SWS_CM_00111\\n     */\\n    void StopOfferService();\\n\\n    void InjectMock(ISkeletonBase& skeleton_mock)\\n    {\\n        skeleton_mock_ = &skeleton_mock;\\n    }\\n\\n  protected:\\n    [[nodiscard]] bool AreBindingsValid() const noexcept;\\n\\n    // Suppress \\\"AUTOSAR C++14 A11-3-1\\\", The rule states: \\\"Friend declarations shall not be used\\\".\\n    // Design decision. This class provides a view to the private members of this class.\\n    // coverity[autosar_cpp14_a11_3_1_violation]\\n    friend class SkeletonBaseView;\\n\\n    /// \\\\brief A Skeleton shall be movable\\n    /// \\\\requirement SWS_CM_00135\\n    SkeletonBase(SkeletonBase&& other) noexcept = default;\\n    SkeletonBase& operator=(SkeletonBase&& other) noexcept = default;\\n\\n  private:\\n    std::unique_ptr<SkeletonBinding> binding_;\\n    SkeletonEvents events_;\\n    SkeletonFields fields_;\\n    SkeletonMethods methods_;\\n    InstanceIdentifier instance_id_;\\n\\n    ISkeletonBase* skeleton_mock_;\\n\\n    [[nodiscard]] score::Result<std::vector<utils::ScopeExit<>>> OfferServiceEvents() const noexcept;\\n    [[nodiscard]] score::Result<std::vector<utils::ScopeExit<>>> OfferServiceFields() const noexcept;\\n\\n    FlagOwner service_offered_flag_;\\n};\\n\\nclass SkeletonBaseView\\n{\\n  public:\\n    explicit SkeletonBaseView(SkeletonBase& skeleton_base);\\n\\n    [[nodiscard]] InstanceIdentifier GetAssociatedInstanceIdentifier() const;\\n\\n    [[nodiscard]] SkeletonBinding& GetBinding() const;\\n\\n    void RegisterEvent(std::string_view event_name, ReferenceToMoveable<SkeletonEventBase>::Reference& event);\\n\\n    void RegisterField(std::string_view field_name, ReferenceToMoveable<SkeletonFieldBase>::Reference& field);\\n\\n    void RegisterMethod(std::string_view method_name, ReferenceToMoveable<SkeletonMethodBase>::Reference& method);\\n\\n    [[nodiscard]] const SkeletonBase::SkeletonEvents& GetEvents() const& noexcept;\\n\\n    [[nodiscard]] const SkeletonBase::SkeletonFields& GetFields() const& noexcept;\\n\\n    [[nodiscard]] const SkeletonBase::SkeletonMethods& GetMethods() const& noexcept;\\n\\n    [[nodiscard]] bool AreBindingsValid() const;\\n\\n  private:\\n    SkeletonBase& skeleton_base_;\\n};\\n\\nstd::optional<InstanceIdentifier> GetInstanceIdentifier(const InstanceSpecifier& specifier);\\n\\n}  // namespace score::mw::com::impl\\n\\n#endif  // SCORE_MW_COM_IMPL_SKELETON_BASE_H\\n\\n\\nFILE score/mw/com/test/all_service_elements/BUILD\\n# *******************************************************************************\\n# Copyright (c) 2026 Contributors to the Eclipse Foundation\\n#\\n# See the NOTICE file(s) distributed with this work for additional\\n# information regarding copyright ownership.\\n#\\n# This program and the accompanying materials are made available under the\\n# terms of the Apache License Version 2.0 which is available at\\n# https://www.apache.org/licenses/LICENSE-2.0\\n#\\n# SPDX-License-Identifier: Apache-2.0\\n# *******************************************************************************\\n\\nload(\\\"@rules_cc//cc:defs.bzl\\\", \\\"cc_binary\\\", \\\"cc_library\\\")\\nload(\\\"@score_baselibs//score/language/safecpp:toolchain_features.bzl\\\", \\\"COMPILER_WARNING_FEATURES\\\")\\nload(\\\"//bazel/tools:json_schema_validator.bzl\\\", \\\"validate_json_schema_test\\\")\\nload(\\\"//score/mw/com/test:pkg_application.bzl\\\", \\\"pkg_application\\\")\\n\\nvalidate_json_schema_test(\\n    name = \\\"validate_lola_schema\\\",\\n    json = \\\"config/mw_com_config.json\\\",\\n    schema = \\\"//score/mw/com:config_schema\\\",\\n    tags = [\\\"lint\\\"],\\n)\\n\\ncc_library(\\n    name = \\\"test_constants\\\",\\n    srcs = [\\\"test_constants.cpp\\\"],\\n    hdrs = [\\\"test_constants.h\\\"],\\n    features = COMPILER_WARNING_FEATURES,\\n    deps = [\\n        \\\":datatype\\\",\\n        \\\"//score/mw/com\\\",\\n    ],\\n)\\n\\ncc_library(\\n    name = \\\"datatype\\\",\\n    srcs = [\\\"all_service_elements_datatype.cpp\\\"],\\n    hdrs = [\\\"all_service_elements_datatype.h\\\"],\\n    features = COMPILER_WARNING_FEATURES,\\n    deps = [\\\"//score/mw/com\\\"],\\n)\\n\\ncc_library(\\n    name = \\\"consumer\\\",\\n    srcs = [\\\"consumer.cpp\\\"],\\n    hdrs = [\\\"consumer.h\\\"],\\n    features = COMPILER_WARNING_FEATURES,\\n    deps = [\\n        \\\":datatype\\\",\\n        \\\":test_constants\\\",\\n        \\\"//score/mw/com\\\",\\n        \\\"//score/mw/com/test/common_test_resources:fail_test\\\",\\n        \\\"//score/mw/com/test/common_test_resources:process_synchronizer\\\",\\n        \\\"//score/mw/com/test/common_test_resources:proxy_container\\\",\\n        \\\"//score/mw/com/test/common_test_resources:proxy_event_receiver\\\",\\n        \\\"//score/mw/com/test/common_test_resources:proxy_event_state_change_notifier\\\",\\n        \\\"//score/mw/com/test/fields/test_resources:getter_and_setter_checkers\\\",\\n    ],\\n)\\n\\ncc_library(\\n    name = \\\"provider\\\",\\n    srcs = [\\\"provider.cpp\\\"],\\n    hdrs = [\\\"provider.h\\\"],\\n    features = COMPILER_WARNING_FEATURES,\\n    deps = [\\n        \\\":datatype\\\",\\n        \\\":test_constants\\\",\\n        \\\"//score/mw/com\\\",\\n        \\\"//score/mw/com/test/common_test_resources:fail_test\\\",\\n        \\\"//score/mw/com/test/common_test_resources:process_synchronizer\\\",\\n        \\\"//score/mw/com/test/common_test_resources:skeleton_container\\\",\\n    ],\\n)\\n\\ncc_binary(\\n    name = \\\"main_provider\\\",\\n    srcs = [\\\"main_provider.cpp\\\"],\\n    data = [\\n        \\\"config/mw_com_config.json\\\",\\n    ],\\n    features = COMPILER_WARNING_FEATURES + [\\n        \\\"aborts_upon_exception\\\",\\n    ],\\n    deps = [\\n        \\\":provider\\\",\\n        \\\"//score/mw/com\\\",\\n        \\\"//score/mw/com/test/common_test_resources:assert_handler\\\",\\n        \\\"//score/mw/com/test/common_test_resources:command_line_parser\\\",\\n        \\\"//score/mw/com/test/common_test_resources:fail_test\\\",\\n        \\\"//score/mw/com/test/common_test_resources:service_instance_manifest_parser\\\",\\n        \\\"//score/mw/com/test/common_test_resources:stop_token_sig_term_handler\\\",\\n        \\\"@score_baselibs//score/mw/log\\\",\\n    ],\\n)\\n\\ncc_binary(\\n    name = \\\"main_consumer\\\",\\n    srcs = [\\\"main_consumer.cpp\\\"],\\n    data = [\\n        \\\"config/mw_com_config.json\\\",\\n    ],\\n    features = COMPILER_WARNING_FEATURES + [\\n        \\\"aborts_upon_exception\\\",\\n    ],\\n    deps = [\\n        \\\":consumer\\\",\\n        \\\"//score/mw/com\\\",\\n        \\\"//score/mw/com/test/common_test_resources:assert_handler\\\",\\n        \\\"//score/mw/com/test/common_test_resources:service_instance_manifest_parser\\\",\\n        \\\"//score/mw/com/test/common_test_resources:stop_token_sig_term_handler\\\",\\n        \\\"@score_baselibs//score/mw/log\\\",\\n    ],\\n)\\n\\ncc_binary(\\n    name = \\\"main_consumer_and_provider\\\",\\n    srcs = [\\\"main_consumer_and_provider.cpp\\\"],\\n    data = [\\n        \\\"config/mw_com_config.json\\\",\\n    ],\\n    features = COMPILER_WARNING_FEATURES + [\\n        \\\"aborts_upon_exception\\\",\\n    ],\\n    deps = [\\n        \\\":consumer\\\",\\n        \\\":provider\\\",\\n        \\\"//score/mw/com\\\",\\n        \\\"//score/mw/com/test/common_test_resources:assert_handler\\\",\\n        \\\"//score/mw/com/test/common_test_resources:service_instance_manifest_parser\\\",\\n        \\\"//score/mw/com/test/common_test_resources:stop_token_sig_term_handler\\\",\\n        \\\"@score_baselibs//score/mw/log\\\",\\n    ],\\n)\\n\\npkg_application(\\n    name = \\\"main_provider-pkg\\\",\\n    app_name = \\\"MainProviderApp\\\",\\n    bin = [\\\":main_provider\\\"],\\n    etc = [\\n        \\\"config/logging.json\\\",\\n        \\\"config/mw_com_config.json\\\",\\n    ],\\n    visibility = [\\n        \\\"//platform/aas/test/mw/com:__pkg__\\\",\\n        \\\"//score/mw/com/test/all_service_elements:__subpackages__\\\",\\n    ],\\n)\\n\\npkg_application(\\n    name = \\\"main_consumer-pkg\\\",\\n    app_name = \\\"MainConsumerApp\\\",\\n    bin = [\\\":main_consumer\\\"],\\n    etc = [\\n        \\\"config/logging.json\\\",\\n        \\\"config/mw_com_config.json\\\",\\n    ],\\n    visibility = [\\n        \\\"//platform/aas/test/mw/com:__pkg__\\\",\\n        \\\"//score/mw/com/test/all_service_elements:__subpackages__\\\",\\n    ],\\n)\\n\\npkg_application(\\n    name = \\\"main_consumer_and_provider-pkg\\\",\\n    app_name = \\\"MainConsumerAndProviderApp\\\",\\n    bin = [\\\":main_consumer_and_provider\\\"],\\n    etc = [\\n        \\\"config/logging.json\\\",\\n        \\\"config/mw_com_config.json\\\",\\n    ],\\n    visibility = [\\n        \\\"//platform/aas/test/mw/com:__pkg__\\\",\\n        \\\"//score/mw/com/test/all_service_elements:__subpackages__\\\",\\n    ],\\n)\\n\\n\\nFILE score/mw/com/test/all_service_elements/all_service_elements_datatype.cpp\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License Version 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n\\n#include \\\"score/mw/com/test/all_service_elements/all_service_elements_datatype.h\\\"\\n\\n\\nFILE score/mw/com/test/all_service_elements/all_service_elements_datatype.h\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License Version 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n#ifndef SCORE_MW_COM_TEST_ALL_SERVICE_ELEMENTS_ALL_SERVICE_ELEMENTS_DATATYPE_H\\n#define SCORE_MW_COM_TEST_ALL_SERVICE_ELEMENTS_ALL_SERVICE_ELEMENTS_DATATYPE_H\\n\\n#include \\\"score/mw/com/types.h\\\"\\n\\n#include <cstdint>\\n\\nnamespace score::mw::com::test\\n{\\n\\nusing TestType = std::int32_t;\\n\\ntemplate <typename Trait>\\nclass AllServiceElementsInterface : public Trait::Base\\n{\\n  public:\\n    using Trait::Base::Base;\\n\\n    // Note. The events, methods and fields are intentionally interleaved since they will be constructed in the order of\\n    // declaration and we want to test that the order of construction does not matter for the underlying implementation.\\n    typename Trait::template Event<TestType> event_1{*this, \\\"event_1\\\"};\\n\\n    typename Trait::template Method<TestType(TestType, TestType)> with_in_args_and_return{*this,\\n                                                                                          \\\"with_in_args_and_return\\\"};\\n\\n    typename Trait::template Field<TestType, WithGetter, WithNotifier> get_and_notifier_enabled_field{\\n        *this,\\n        \\\"get_and_notifier_enabled_field\\\"};\\n\\n    typename Trait::template Method<void(TestType, TestType)> with_in_args_only{*this, \\\"with_in_args_only\\\"};\\n\\n    typename Trait::template Field<TestType, WithGetter> get_only_enabled_field{*this, \\\"get_only_enabled_field\\\"};\\n\\n    typename Trait::template Method<TestType()> with_return_only{*this, \\\"with_return_only\\\"};\\n\\n    typename Trait::template Field<TestType, WithNotifier> notifier_only_enabled_field{*this,\\n                                                                                       \\\"notifier_only_enabled_field\\\"};\\n\\n    typename Trait::template Method<void()> without_args_or_return{*this, \\\"without_args_or_return\\\"};\\n\\n    typename Trait::template Field<TestType, WithSetter, WithGetter, WithNotifier>\\n        set_and_get_and_notifier_enabled_field{*this, \\\"set_and_get_and_notifier_enabled_field\\\"};\\n\\n    typename Trait::template Field<TestType, WithSetter, WithGetter> set_and_get_enabled_field{\\n        *this,\\n        \\\"set_and_get_enabled_field\\\"};\\n\\n    typename Trait::template Event<TestType> event_2{*this, \\\"event_2\\\"};\\n\\n    typename Trait::template Field<TestType, WithSetter, WithNotifier> set_and_notifier_enabled_field{\\n        *this,\\n        \\\"set_and_notifier_enabled_field\\\"};\\n};\\n\\nusing AllServiceElementsProxy = score::mw::com::AsProxy<AllServiceElementsInterface>;\\nusing AllServiceElementsSkeleton = score::mw::com::AsSkeleton<AllServiceElementsInterface>;\\n\\n}  // namespace score::mw::com::test\\n\\n#endif  // SCORE_MW_COM_TEST_ALL_SERVICE_ELEMENTS_ALL_SERVICE_ELEMENTS_DATATYPE_H\\n\\n\\nFILE score/mw/com/test/all_service_elements/config/logging.json\\n{\\n  \\\"appId\\\": \\\"ASET\\\",\\n  \\\"appDesc\\\": \\\"all_service_elements\\\",\\n  \\\"logLevel\\\": \\\"kDebug\\\",\\n  \\\"logLevelThresholdConsole\\\": \\\"kDebug\\\",\\n  \\\"logMode\\\": \\\"kRemote\\\"\\n}\\n\\n\\nFILE score/mw/com/test/all_service_elements/config/mw_com_config.json\\n{\\n  \\\"serviceTypes\\\": [\\n    {\\n      \\\"serviceTypeName\\\": \\\"/score/mw/com/test/all_service_elements/all_service_elements_type\\\",\\n      \\\"version\\\": {\\n        \\\"major\\\": 1,\\n        \\\"minor\\\": 0\\n      },\\n      \\\"bindings\\\": [\\n        {\\n          \\\"binding\\\": \\\"SHM\\\",\\n          \\\"serviceId\\\": 3428,\\n          \\\"events\\\": [\\n            {\\n              \\\"eventName\\\": \\\"event_1\\\",\\n              \\\"eventId\\\": 1\\n            },\\n            {\\n              \\\"eventName\\\": \\\"event_2\\\",\\n              \\\"eventId\\\": 2\\n            }\\n          ],\\n          \\\"fields\\\": [\\n            {\\n              \\\"fieldName\\\": \\\"notifier_only_enabled_field\\\",\\n              \\\"fieldId\\\": 3\\n            },\\n            {\\n              \\\"fieldName\\\": \\\"set_and_notifier_enabled_field\\\",\\n              \\\"fieldId\\\": 4\\n            },\\n            {\\n              \\\"fieldName\\\": \\\"get_only_enabled_field\\\",\\n              \\\"fieldId\\\": 5\\n            },\\n            {\\n              \\\"fieldName\\\": \\\"get_and_notifier_enabled_field\\\",\\n              \\\"fieldId\\\": 6\\n            },\\n            {\\n              \\\"fieldName\\\": \\\"set_and_get_enabled_field\\\",\\n              \\\"fieldId\\\": 7\\n            },\\n            {\\n              \\\"fieldName\\\": \\\"set_and_get_and_notifier_enabled_field\\\",\\n              \\\"fieldId\\\": 8\\n            }\\n          ],\\n          \\\"methods\\\": [\\n            {\\n              \\\"methodName\\\": \\\"with_in_args_and_return\\\",\\n              \\\"methodId\\\": 9\\n            },\\n            {\\n              \\\"methodName\\\": \\\"with_in_args_only\\\",\\n              \\\"methodId\\\": 10\\n            },\\n            {\\n              \\\"methodName\\\": \\\"with_return_only\\\",\\n              \\\"methodId\\\": 11\\n            },\\n            {\\n              \\\"methodName\\\": \\\"without_args_or_return\\\",\\n              \\\"methodId\\\": 12\\n            }\\n          ]\\n        }\\n      ]\\n    }\\n  ],\\n  \\\"serviceInstances\\\": [\\n    {\\n      \\\"instanceSpecifier\\\": \\\"/score/mw/com/test/all_service_elements/all_service_elements_instance\\\",\\n      \\\"serviceTypeName\\\": \\\"/score/mw/com/test/all_service_elements/all_service_elements_type\\\",\\n      \\\"version\\\": {\\n        \\\"major\\\": 1,\\n        \\\"minor\\\": 0\\n      },\\n      \\\"instances\\\": [\\n        {\\n          \\\"instanceId\\\": 1024,\\n          \\\"asil-level\\\": \\\"B\\\",\\n          \\\"binding\\\": \\\"SHM\\\",\\n          \\\"events\\\": [\\n            {\\n              \\\"eventName\\\": \\\"event_1\\\",\\n              \\\"maxSamples\\\": 10,\\n              \\\"maxSubscribers\\\": 3\\n            },\\n            {\\n              \\\"eventName\\\": \\\"event_2\\\",\\n              \\\"maxSamples\\\": 10,\\n              \\\"maxSubscribers\\\": 3\\n            }\\n          ],\\n          \\\"fields\\\": [\\n            {\\n              \\\"fieldName\\\": \\\"notifier_only_enabled_field\\\",\\n              \\\"maxSubscribers\\\": 1,\\n              \\\"numberOfSampleSlots\\\": 4\\n            },\\n            {\\n              \\\"fieldName\\\": \\\"set_and_notifier_enabled_field\\\",\\n              \\\"maxSubscribers\\\": 1,\\n              \\\"numberOfSampleSlots\\\": 4\\n            },\\n            {\\n              \\\"fieldName\\\": \\\"get_only_enabled_field\\\",\\n              \\\"maxSubscribers\\\": 1,\\n              \\\"numberOfSampleSlots\\\": 4\\n            },\\n            {\\n              \\\"fieldName\\\": \\\"get_and_notifier_enabled_field\\\",\\n              \\\"maxSubscribers\\\": 1,\\n              \\\"numberOfSampleSlots\\\": 4\\n            },\\n            {\\n              \\\"fieldName\\\": \\\"set_and_get_enabled_field\\\",\\n              \\\"maxSubscribers\\\": 1,\\n              \\\"numberOfSampleSlots\\\": 4\\n            },\\n            {\\n              \\\"fieldName\\\": \\\"set_and_get_and_notifier_enabled_field\\\",\\n              \\\"maxSubscribers\\\": 1,\\n              \\\"numberOfSampleSlots\\\": 4\\n            }\\n          ],\\n          \\\"methods\\\": [\\n            {\\n              \\\"methodName\\\": \\\"with_in_args_and_return\\\",\\n              \\\"queueSize\\\": 1\\n            },\\n            {\\n              \\\"methodName\\\": \\\"with_in_args_only\\\",\\n              \\\"queueSize\\\": 1\\n            },\\n            {\\n              \\\"methodName\\\": \\\"with_return_only\\\",\\n              \\\"queueSize\\\": 1\\n            },\\n            {\\n              \\\"methodName\\\": \\\"without_args_or_return\\\",\\n              \\\"queueSize\\\": 1\\n            }\\n          ]\\n        }\\n      ]\\n    }\\n  ],\\n  \\\"global\\\": {\\n    \\\"asil-level\\\": \\\"B\\\"\\n  }\\n}\\n\\n\\nFILE score/mw/com/test/all_service_elements/consumer.cpp\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n#include \\\"score/mw/com/test/all_service_elements/consumer.h\\\"\\n\\n#include \\\"score/mw/com/test/all_service_elements/all_service_elements_datatype.h\\\"\\n#include \\\"score/mw/com/test/all_service_elements/test_constants.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/fail_test.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/process_synchronizer.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/proxy_container.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/proxy_event_receiver.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/proxy_event_state_change_notifier.h\\\"\\n#include \\\"score/mw/com/test/fields/test_resources/getter_and_setter_checkers.h\\\"\\n\\n#include <future>\\n#include <iostream>\\n#include <vector>\\n\\nnamespace score::mw::com::test\\n{\\nnamespace\\n{\\n\\nvoid CallMethodsOrFail(AllServiceElementsProxy& proxy)\\n{\\n    const auto with_in_args_and_return_result =\\n        proxy.with_in_args_and_return(kInArgsAndReturnMethodTestValueA, kInArgsAndReturnMethodTestValueB);\\n    if (!with_in_args_and_return_result.has_value())\\n    {\\n        FailTest(kFailureMessagePrefix,\\n                 \\\" Consumer: with_in_args_and_return call failed: \\\",\\n                 with_in_args_and_return_result.error());\\n    }\\n    const auto expected_sum = kInArgsAndReturnMethodTestValueA + kInArgsAndReturnMethodTestValueB;\\n    if (*(with_in_args_and_return_result.value()) != expected_sum)\\n    {\\n        FailTest(kFailureMessagePrefix,\\n                 \\\" Consumer: with_in_args_and_return expected \\\",\\n                 expected_sum,\\n                 \\\" but got \\\",\\n                 *(with_in_args_and_return_result.value()));\\n    }\\n\\n    const auto with_in_args_only_result =\\n        proxy.with_in_args_only(kInArgOnlyMethodTestValueA, kInArgOnlyMethodTestValueB);\\n    if (!with_in_args_only_result.has_value())\\n    {\\n        FailTest(kFailureMessagePrefix, \\\" Consumer: with_in_args_only call failed: \\\", with_in_args_only_result.error());\\n    }\\n\\n    const auto with_return_only_result = proxy.with_return_only();\\n    if (!with_return_only_result.has_value())\\n    {\\n        FailTest(kFailureMessagePrefix, \\\" Consumer: with_return_only call failed: \\\", with_return_only_result.error());\\n    }\\n    if (*(with_return_only_result.value()) != kReturnOnlyMethodReturnValue)\\n    {\\n        FailTest(kFailureMessagePrefix,\\n                 \\\" Consumer: with_return_only expected \\\",\\n                 kReturnOnlyMethodReturnValue,\\n                 \\\" but got \\\",\\n                 *(with_return_only_result.value()));\\n    }\\n\\n    const auto without_args_or_return_result = proxy.without_args_or_return();\\n    if (!without_args_or_return_result.has_value())\\n    {\\n        FailTest(kFailureMessagePrefix,\\n                 \\\" Consumer: without_args_or_return call failed: \\\",\\n                 without_args_or_return_result.error());\\n    }\\n}\\n\\ntemplate <typename EventType>\\nvoid SubscribeAndReceiveEventsOrFail(EventType& proxy_event,\\n                                     const std::vector<TestType>& expected_values,\\n                                     const score::cpp::stop_token& stop_token)\\n{\\n    ProxyEventReceiver event_receiver{proxy_event};\\n    ProxyEventStateChangeNotifier subscription_notifier{proxy_event};\\n\\n    const auto subscribe_event_result = proxy_event.Subscribe(expected_values.size());\\n    if (!subscribe_event_result.has_value())\\n    {\\n        FailTest(kFailureMessagePrefix, \\\" Consumer: Subscribe to event failed: \\\", subscribe_event_result.error());\\n    }\\n\\n    if (!subscription_notifier.WaitForStateChange(stop_token, SubscriptionState::kSubscribed))\\n    {\\n        FailTest(kFailureMessagePrefix, \\\" Consumer: Event subscription did not reach kSubscribed\\\");\\n    }\\n\\n    if (!event_receiver.WaitForSamples(stop_token, expected_values))\\n    {\\n        FailTest(kFailureMessagePrefix, \\\" Consumer: Did not receive all expected samples for event\\\");\\n    }\\n}\\n\\n}  // namespace\\n\\nvoid RunConsumer(const score::cpp::stop_token& stop_token)\\n{\\n    auto process_synchronizer_result = ProcessSynchronizer::Create(kInterprocessNotificationShmPath);\\n    if (!process_synchronizer_result.has_value())\\n    {\\n        FailTest(kFailureMessagePrefix, \\\" Consumer: Could not create consumer-done ProcessSynchronizer\\\");\\n    }\\n    ExitFunctionGuard exit_guard{[&process_synchronizer_result]() {\\n        process_synchronizer_result->Notify();\\n    }};\\n\\n    // Step 1. Find service and create proxy\\n    std::cout << \\\"\\\\nConsumer: Step 1 - Find service and create proxy\\\" << std::endl;\\n    ProxyContainer<AllServiceElementsProxy> proxy_container{};\\n    proxy_container.CreateProxy(kInstanceSpecifier, kFailureMessagePrefix);\\n    auto& proxy = proxy_container.GetProxy();\\n\\n    // Step 2. Call all methods and verify their results\\n    std::cout << \\\"\\\\nConsumer: Step 2 - Call methods\\\" << std::endl;\\n    CallMethodsOrFail(proxy);\\n\\n    // Step 3. Subscribe to events and fields and verify received samples. We call these asynchronously to ensure that\\n    // there are no issues with calling these functions on different service elements concurrently. We ensure that each\\n    // step is finished before the next one begins because the test itself assumes this (e.g. calling Get will get the\\n    // latest value that was received by GetNewSamples)\\n    std::cout << \\\"\\\\nConsumer: Step 3 - Test events\\\" << std::endl;\\n    std::vector<std::future<void>> step_3_futures{};\\n    // Call a lambda within each async since the compiler cannot deduce the template type when calling\\n    // SubscribeAndReceiveEventsOrFail directly within std::async.\\n    step_3_futures.push_back(std::async(std::launch::async, [&]() {\\n        SubscribeAndReceiveEventsOrFail(proxy.event_1, kEvent1ValuesToSend, stop_token);\\n    }));\\n    step_3_futures.push_back(std::async(std::launch::async, [&]() {\\n        SubscribeAndReceiveEventsOrFail(proxy.event_2, kEvent2ValuesToSend, stop_token);\\n    }));\\n    step_3_futures.push_back(std::async(std::launch::async, [&]() {\\n        SubscribeAndReceiveEventsOrFail(proxy.get_and_notifier_enabled_field, kAllGetAndNotifierValues, stop_token);\\n    }));\\n    step_3_futures.push_back(std::async(std::launch::async, [&]() {\\n        SubscribeAndReceiveEventsOrFail(\\n            proxy.set_and_get_and_notifier_enabled_field, kAllSetAndGetAndNotifierValues, stop_token);\\n    }));\\n    step_3_futures.push_back(std::async(std::launch::async, [&]() {\\n        SubscribeAndReceiveEventsOrFail(proxy.notifier_only_enabled_field, kAllNotifierOnlyValues, stop_token);\\n    }));\\n    step_3_futures.push_back(std::async(std::launch::async, [&]() {\\n        SubscribeAndReceiveEventsOrFail(proxy.set_and_notifier_enabled_field, kAllSetAndNotifierValues, stop_token);\\n    }));\\n\\n    for (auto& future : step_3_futures)\\n    {\\n        future.get();\\n    }\\n\\n    // Step 4. Test getters\\n    std::cout << \\\"\\\\nConsumer: Step 4 - Test getters\\\" << std::endl;\\n    std::vector<std::future<void>> step_4_futures{};\\n    step_4_futures.push_back(std::async(std::launch::async, [&]() {\\n        CallGetAndCheckValue(proxy.get_only_enabled_field, kGetOnlyFieldInitialValue);\\n    }));\\n    step_4_futures.push_back(std::async(std::launch::async, [&]() {\\n        CallGetAndCheckValue(proxy.get_and_notifier_enabled_field, kGetAndNotifierFieldValuesToSend.back());\\n    }));\\n    step_4_futures.push_back(std::async(std::launch::async, [&]() {\\n        CallGetAndCheckValue(proxy.set_and_get_enabled_field, kSetAndGetFieldInitialValue);\\n    }));\\n    step_4_futures.push_back(std::async(std::launch::async, [&]() {\\n        CallGetAndCheckValue(proxy.set_and_get_and_notifier_enabled_field,\\n                             kSetAndGetAndNotifierFieldValuesToSend.back());\\n    }));\\n\\n    for (auto& future : step_4_futures)\\n    {\\n        future.get();\\n    }\\n\\n    // Step 5. Test setters\\n    std::cout << \\\"\\\\nConsumer: Step 5 - Test setters\\\" << std::endl;\\n    std::vector<std::future<void>> step_5_futures{};\\n    step_5_futures.push_back(std::async(std::launch::async, [&]() {\\n        CallSetAndCheckReturnValue(\\n            proxy.set_and_get_enabled_field, kSetAndGetRequestValue, (kSetAndGetRequestValue * 2) + 1);\\n    }));\\n    step_5_futures.push_back(std::async(std::launch::async, [&]() {\\n        CallSetAndCheckReturnValue(\\n            proxy.set_and_notifier_enabled_field, kSetAndNotifierRequestValue, (kSetAndNotifierRequestValue * 2) + 1);\\n    }));\\n    step_5_futures.push_back(std::async(std::launch::async, [&]() {\\n        CallSetAndCheckReturnValue(proxy.set_and_get_and_notifier_enabled_field,\\n                                   kSetAndGetAndNotifierRequestValue,\\n                                   (kSetAndGetAndNotifierRequestValue * 2) + 1);\\n    }));\\n\\n    for (auto& future : step_5_futures)\\n    {\\n        future.get();\\n    }\\n}\\n\\n}  // namespace score::mw::com::test\\n\\n\\nFILE score/mw/com/test/all_service_elements/consumer.h\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n\\n#ifndef SCORE_MW_COM_TEST_ALL_SERVICE_ELEMENTS_CONSUMER_H\\n#define SCORE_MW_COM_TEST_ALL_SERVICE_ELEMENTS_CONSUMER_H\\n\\n#include <score/stop_token.hpp>\\n\\nnamespace score::mw::com::test\\n{\\n\\nvoid RunConsumer(const score::cpp::stop_token& stop_token);\\n\\n}  // namespace score::mw::com::test\\n\\n#endif  // SCORE_MW_COM_TEST_ALL_SERVICE_ELEMENTS_CONSUMER_H\\n\\n\\nFILE score/mw/com/test/all_service_elements/integration_test/BUILD\\n# *******************************************************************************\\n# Copyright (c) 2026 Contributors to the Eclipse Foundation\\n#\\n# See the NOTICE file(s) distributed with this work for additional\\n# information regarding copyright ownership.\\n#\\n# This program and the accompanying materials are made available under the\\n# terms of the Apache License Version 2.0 which is available at\\n# https://www.apache.org/licenses/LICENSE-2.0\\n#\\n# SPDX-License-Identifier: Apache-2.0\\n# *******************************************************************************\\n\\nload(\\\"@rules_pkg//pkg:mappings.bzl\\\", \\\"pkg_filegroup\\\")\\nload(\\\"//quality/integration_testing:integration_testing.bzl\\\", \\\"integration_test\\\")\\n\\nintegration_test(\\n    name = \\\"all_service_elements_same_process_test\\\",\\n    srcs = [\\n        \\\"all_service_elements_same_process_test.py\\\",\\n    ],\\n    filesystem = \\\"//score/mw/com/test/all_service_elements:main_consumer_and_provider-pkg\\\",\\n)\\n\\npkg_filegroup(\\n    name = \\\"different_processes_filesystem\\\",\\n    srcs = [\\n        \\\"//score/mw/com/test/all_service_elements:main_consumer-pkg\\\",\\n        \\\"//score/mw/com/test/all_service_elements:main_provider-pkg\\\",\\n    ],\\n)\\n\\nintegration_test(\\n    name = \\\"all_service_elements_different_processes_test\\\",\\n    srcs = [\\n        \\\"all_service_elements_different_processes_test.py\\\",\\n    ],\\n    filesystem = \\\":different_processes_filesystem\\\",\\n)\\n\\n\\nFILE score/mw/com/test/all_service_elements/integration_test/all_service_elements_different_processes_test.py\\n# *******************************************************************************\\n# Copyright (c) 2026 Contributors to the Eclipse Foundation\\n#\\n# See the NOTICE file(s) distributed with this work for additional\\n# information regarding copyright ownership.\\n#\\n# This program and the accompanying materials are made available under the\\n# terms of the Apache License Version 2.0 which is available at\\n# https://www.apache.org/licenses/LICENSE-2.0\\n#\\n# SPDX-License-Identifier: Apache-2.0\\n# *******************************************************************************\\n\\n\\ndef provider(target, **kwargs):\\n    args = [\\\"--service_instance_manifest\\\", \\\"./etc/mw_com_config.json\\\"]\\n    return target.wrap_exec(\\n        \\\"bin/main_provider\\\",\\n        args,\\n        cwd=\\\"/opt/MainProviderApp\\\",\\n        wait_on_exit=True,\\n        **kwargs,\\n    )\\n\\n\\ndef consumer(target, **kwargs):\\n    args = [\\\"--service_instance_manifest\\\", \\\"./etc/mw_com_config.json\\\"]\\n    return target.wrap_exec(\\n        \\\"bin/main_consumer\\\",\\n        args,\\n        cwd=\\\"/opt/MainConsumerApp\\\",\\n        wait_on_exit=True,\\n        **kwargs,\\n    )\\n\\n\\ndef test_basic_acceptance_different_processes_test(target):\\n    \\\"\\\"\\\"Test LoLa functionality between provider and consumer which contain fields, methods\\n    and events in the different processes.\\n\\n    The first process creates a Skeleton instance with events, fields and methods, verifying\\n    the service can be offered.\\n\\n    The second process creates a Proxy instance subscribing to the Skeleton, interacting with\\n    all events, fields and methods, verifying both succeed with expected return values.\\n    \\\"\\\"\\\"\\n    with provider(target), consumer(target):\\n        pass\\n\\n\\nFILE score/mw/com/test/all_service_elements/integration_test/all_service_elements_same_process_test.py\\n# *******************************************************************************\\n# Copyright (c) 2026 Contributors to the Eclipse Foundation\\n#\\n# See the NOTICE file(s) distributed with this work for additional\\n# information regarding copyright ownership.\\n#\\n# This program and the accompanying materials are made available under the\\n# terms of the Apache License Version 2.0 which is available at\\n# https://www.apache.org/licenses/LICENSE-2.0\\n#\\n# SPDX-License-Identifier: Apache-2.0\\n# *******************************************************************************\\n\\n\\ndef consumer_and_provider(target, **kwargs):\\n    args = [\\\"--service_instance_manifest\\\", \\\"./etc/mw_com_config.json\\\"]\\n    return target.wrap_exec(\\n        \\\"bin/main_consumer_and_provider\\\",\\n        args,\\n        cwd=\\\"/opt/MainConsumerAndProviderApp\\\",\\n        wait_on_exit=True,\\n        **kwargs,\\n    )\\n\\n\\ndef test_basic_acceptance_same_process_test(target):\\n    \\\"\\\"\\\"Test LoLa functionality between provider and consumer which contain fields, methods and events in the same process.\\n\\n    The test starts a single process with two threads. The first thread creates a Skeleton\\n    instance with events, fields and methods. The second thread creates a Proxy\\n    subscribing to the Skeleton, interacting with all events, fields and methods, verifying both\\n    succeed with expected return values.\\n    \\\"\\\"\\\"\\n    with consumer_and_provider(target):\\n        pass\\n\\n\\nFILE score/mw/com/test/all_service_elements/main_consumer.cpp\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n#include \\\"score/mw/com/runtime.h\\\"\\n#include \\\"score/mw/com/test/all_service_elements/consumer.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/assert_handler.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/service_instance_manifest_parser.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/stop_token_sig_term_handler.h\\\"\\n\\n#include <cstdlib>\\n\\nint main(int argc, const char** argv)\\n{\\n    auto service_instance_manifest_path = score::mw::com::test::ParseServiceInstanceManifest(argc, argv);\\n\\n    score::mw::com::test::SetupAssertHandler();\\n    score::mw::com::runtime::InitializeRuntime(\\n        score::mw::com::runtime::RuntimeConfiguration{service_instance_manifest_path});\\n\\n    score::cpp::stop_source stop_source{};\\n    const bool sig_term_handler_setup_success = score::mw::com::SetupStopTokenSigTermHandler(stop_source);\\n    if (!sig_term_handler_setup_success)\\n    {\\n        std::cerr << \\\"Unable to set signal handler for SIGINT and/or SIGTERM, cautiously continuing\\\\n\\\";\\n    }\\n\\n    score::mw::com::test::RunConsumer(stop_source.get_token());\\n    return EXIT_SUCCESS;\\n}\\n\\n\\nFILE score/mw/com/test/all_service_elements/main_consumer_and_provider.cpp\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n\\n#include \\\"score/mw/com/runtime.h\\\"\\n#include \\\"score/mw/com/test/all_service_elements/consumer.h\\\"\\n#include \\\"score/mw/com/test/all_service_elements/provider.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/assert_handler.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/service_instance_manifest_parser.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/stop_token_sig_term_handler.h\\\"\\n\\n#include <cstdlib>\\n#include <future>\\n#include <iostream>\\n\\nint main(int argc, const char** argv)\\n{\\n    auto service_instance_manifest_path = score::mw::com::test::ParseServiceInstanceManifest(argc, argv);\\n\\n    score::mw::com::test::SetupAssertHandler();\\n    score::mw::com::runtime::InitializeRuntime(\\n        score::mw::com::runtime::RuntimeConfiguration{service_instance_manifest_path});\\n\\n    score::cpp::stop_source stop_source{};\\n    const bool sig_term_handler_setup_success = score::mw::com::SetupStopTokenSigTermHandler(stop_source);\\n    if (!sig_term_handler_setup_success)\\n    {\\n        std::cerr << \\\"Unable to set signal handler for SIGINT and/or SIGTERM, cautiously continuing\\\\n\\\";\\n    }\\n\\n    auto provider_future = std::async(std::launch::async, score::mw::com::test::RunProvider, stop_source.get_token());\\n    auto consumer_future = std::async(std::launch::async, score::mw::com::test::RunConsumer, stop_source.get_token());\\n\\n    provider_future.get();\\n    consumer_future.get();\\n\\n    std::cout << \\\"Provider and Consumer completed successfully\\\" << std::endl;\\n    return EXIT_SUCCESS;\\n}\\n\\n\\nFILE score/mw/com/test/all_service_elements/main_provider.cpp\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n\\n#include \\\"score/mw/com/runtime.h\\\"\\n#include \\\"score/mw/com/test/all_service_elements/provider.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/assert_handler.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/service_instance_manifest_parser.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/stop_token_sig_term_handler.h\\\"\\n\\n#include <cstdlib>\\n#include <iostream>\\n\\nint main(int argc, const char** argv)\\n{\\n    auto service_instance_manifest_path = score::mw::com::test::ParseServiceInstanceManifest(argc, argv);\\n\\n    score::mw::com::test::SetupAssertHandler();\\n    score::mw::com::runtime::InitializeRuntime(\\n        score::mw::com::runtime::RuntimeConfiguration{service_instance_manifest_path});\\n\\n    score::cpp::stop_source stop_source{};\\n    const bool sig_term_handler_setup_success = score::mw::com::SetupStopTokenSigTermHandler(stop_source);\\n    if (!sig_term_handler_setup_success)\\n    {\\n        std::cerr << \\\"Unable to set signal handler for SIGINT and/or SIGTERM, cautiously continuing\\\\n\\\";\\n    }\\n\\n    score::mw::com::test::RunProvider(stop_source.get_token());\\n    return EXIT_SUCCESS;\\n}\\n\\n\\nFILE score/mw/com/test/all_service_elements/provider.cpp\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n#include \\\"score/mw/com/test/all_service_elements/provider.h\\\"\\n\\n#include \\\"score/mw/com/test/all_service_elements/all_service_elements_datatype.h\\\"\\n#include \\\"score/mw/com/test/all_service_elements/test_constants.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/fail_test.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/process_synchronizer.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/skeleton_container.h\\\"\\n\\n#include <iostream>\\n\\nnamespace score::mw::com::test\\n{\\nnamespace\\n{\\n\\ntemplate <typename SkeletonFieldType>\\nvoid UpdateField(SkeletonFieldType& field, const TestType value)\\n{\\n    const auto update_result = field.Update(value);\\n    if (!update_result.has_value())\\n    {\\n        FailTest(kFailureMessagePrefix, \\\" Provider: Unable to update with value \\\", value, \\\": \\\", update_result.error());\\n    }\\n}\\n\\ntemplate <typename SkeletonEventType>\\nvoid SendEventSamplesOrFail(SkeletonEventType& skeleton_event, const std::vector<TestType>& values_to_send)\\n{\\n    for (const auto value : values_to_send)\\n    {\\n        const auto send_result = skeleton_event.Send(value);\\n        if (!send_result.has_value())\\n        {\\n            FailTest(kFailureMessagePrefix, \\\" Provider: Unable to send with value \\\", value, \\\": \\\", send_result.error());\\n        }\\n    }\\n}\\n\\ntemplate <typename SkeletonFieldType>\\nvoid SendFieldSamplesOrFail(SkeletonFieldType& skeleton_field, const std::vector<TestType>& values_to_send)\\n{\\n    for (const auto value : values_to_send)\\n    {\\n        UpdateField(skeleton_field, value);\\n    }\\n}\\n\\nvoid ValueTransformSetHandler(TestType& value) noexcept\\n{\\n    value = (value * 2) + 1;\\n}\\n\\nvoid RegisterFieldHandlersOrFail(AllServiceElementsSkeleton& skeleton)\\n{\\n    const auto register_setter_and_notifier_result =\\n        skeleton.set_and_notifier_enabled_field.RegisterSetHandler([](TestType& value) noexcept {\\n            ValueTransformSetHandler(value);\\n        });\\n    if (!register_setter_and_notifier_result.has_value())\\n    {\\n        FailTest(kFailureMessagePrefix,\\n                 \\\" Provider: Unable to register setter_and_notifier_field set handler: \\\",\\n                 register_setter_and_notifier_result.error());\\n    }\\n\\n    const auto register_setter_and_getter_result =\\n        skeleton.set_and_get_enabled_field.RegisterSetHandler([](TestType& value) noexcept {\\n            ValueTransformSetHandler(value);\\n        });\\n    if (!register_setter_and_getter_result.has_value())\\n    {\\n        FailTest(kFailureMessagePrefix,\\n                 \\\" Provider: Unable to register setter_and_getter_field set handler: \\\",\\n                 register_setter_and_getter_result.error());\\n    }\\n\\n    const auto register_setter_getter_notifier_result =\\n        skeleton.set_and_get_and_notifier_enabled_field.RegisterSetHandler([](TestType& value) noexcept {\\n            ValueTransformSetHandler(value);\\n        });\\n    if (!register_setter_getter_notifier_result.has_value())\\n    {\\n        FailTest(kFailureMessagePrefix,\\n                 \\\" Provider: Unable to register setter_getter_notifier_field set handler: \\\",\\n                 register_setter_getter_notifier_result.error());\\n    }\\n}\\n\\nvoid RegisterMethodHandlersOrFail(AllServiceElementsSkeleton& skeleton)\\n{\\n    auto handler_with_in_args_and_return = [](TestType& return_value, const TestType& a, const TestType& b) {\\n        std::cout << \\\"Provider: with_in_args_and_return called with \\\" << a << \\\" + \\\" << b << std::endl;\\n        return_value = a + b;\\n    };\\n    const auto register_in_args_and_return_result =\\n        skeleton.with_in_args_and_return.RegisterHandler(std::move(handler_with_in_args_and_return));\\n    if (!register_in_args_and_return_result)\\n    {\\n        FailTest(kFailureMessagePrefix, \\\" Provider: Failed to register with_in_args_and_return handler\\\");\\n    }\\n\\n    auto handler_with_in_args_only = [](const TestType& a, const TestType& b) {\\n        SCORE_LANGUAGE_FUTURECPP_ASSERT_MESSAGE(a == kInArgOnlyMethodTestValueA, \\\"Unexpected first InArg received!\\\");\\n        SCORE_LANGUAGE_FUTURECPP_ASSERT_MESSAGE(b == kInArgOnlyMethodTestValueB, \\\"Unexpected second InArg received!\\\");\\n    };\\n    const auto register_with_in_args_only_result =\\n        skeleton.with_in_args_only.RegisterHandler(std::move(handler_with_in_args_only));\\n    if (!register_with_in_args_only_result)\\n    {\\n        FailTest(kFailureMessagePrefix, \\\" Provider: Failed to register with_in_args_only handler\\\");\\n    }\\n\\n    auto handler_with_return_only = [](TestType& return_value) {\\n        return_value = kReturnOnlyMethodReturnValue;\\n    };\\n    const auto register_with_return_only_result =\\n        skeleton.with_return_only.RegisterHandler(std::move(handler_with_return_only));\\n    if (!register_with_return_only_result)\\n    {\\n        FailTest(kFailureMessagePrefix, \\\" Provider: Failed to register with_return_only handler\\\");\\n    }\\n\\n    auto handler_without_in_args_or_return = []() {};\\n    const auto register_without_in_args_or_return_result =\\n        skeleton.without_args_or_return.RegisterHandler(std::move(handler_without_in_args_or_return));\\n    if (!register_without_in_args_or_return_result)\\n    {\\n        FailTest(kFailureMessagePrefix, \\\" Provider: Failed to register without_args_or_return handler\\\");\\n    }\\n}\\n\\n}  // namespace\\n\\nvoid RunProvider(const score::cpp::stop_token& stop_token)\\n{\\n    auto process_synchronizer_result = ProcessSynchronizer::Create(kInterprocessNotificationShmPath);\\n    if (!process_synchronizer_result.has_value())\\n    {\\n        FailTest(kFailureMessagePrefix, \\\" Provider: Could not create ProcessSynchronizer\\\");\\n    }\\n\\n    // Step 1. Create skeleton\\n    std::cout << \\\"\\\\nProvider: Step 1 - Create skeleton\\\" << std::endl;\\n    SkeletonContainer<AllServiceElementsSkeleton> skeleton_container{};\\n    skeleton_container.CreateSkeleton(kInstanceSpecifier, kFailureMessagePrefix);\\n    auto& service = skeleton_container.GetSkeleton();\\n\\n    // Step 2. Register field handlers\\n    std::cout << \\\"\\\\nProvider: Step 2 - Register field handlers\\\" << std::endl;\\n    RegisterFieldHandlersOrFail(service);\\n\\n    // Step 3. Register method handlers\\n    std::cout << \\\"\\\\nProvider: Step 3 - Register method handlers\\\" << std::endl;\\n    RegisterMethodHandlersOrFail(service);\\n\\n    // Step 4. Set initial value for all fields\\n    std::cout << \\\"\\\\nProvider: Step 4 - Set initial field values\\\" << std::endl;\\n    UpdateField(service.get_only_enabled_field, kGetOnlyFieldInitialValue);\\n    UpdateField(service.set_and_get_enabled_field, kSetAndGetFieldInitialValue);\\n    UpdateField(service.get_and_notifier_enabled_field, kGetAndNotifierFieldInitialValue);\\n    UpdateField(service.set_and_notifier_enabled_field, kSetAndNotifierFieldInitialValue);\\n    UpdateField(service.set_and_get_and_notifier_enabled_field, kSetAndGetAndNotifierFieldInitialValue);\\n    UpdateField(service.notifier_only_enabled_field, kNotifierOnlyFieldInitialValue);\\n\\n    // Step 5. Offer service\\n    std::cout << \\\"\\\\nProvider: Step 5 - Offer service\\\" << std::endl;\\n    skeleton_container.OfferService(kFailureMessagePrefix);\\n\\n    // Step 6. Send event and field samples\\n    std::cout << \\\"\\\\nProvider: Step 6 - Send event and field samples\\\" << std::endl;\\n    SendEventSamplesOrFail(service.event_1, kEvent1ValuesToSend);\\n    SendEventSamplesOrFail(service.event_2, kEvent2ValuesToSend);\\n    SendFieldSamplesOrFail(service.get_and_notifier_enabled_field, kGetAndNotifierFieldValuesToSend);\\n    SendFieldSamplesOrFail(service.set_and_notifier_enabled_field, kSetAndNotifierFieldValuesToSend);\\n    SendFieldSamplesOrFail(service.set_and_get_and_notifier_enabled_field, kSetAndGetAndNotifierFieldValuesToSend);\\n    SendFieldSamplesOrFail(service.notifier_only_enabled_field, kNotifierOnlyFieldValuesToSend);\\n\\n    // Step 7. Wait for consumer to finish\\n    std::cout << \\\"\\\\nProvider: Step 7 - Wait for consumer done notification\\\" << std::endl;\\n    if (!process_synchronizer_result->WaitWithAbort(stop_token))\\n    {\\n        FailTest(kFailureMessagePrefix, \\\" Provider: WaitWithAbort was stopped by stop_token instead of notification\\\");\\n    }\\n}\\n\\n}  // namespace score::mw::com::test\\n\\n\\nFILE score/mw/com/test/all_service_elements/provider.h\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n\\n#ifndef SCORE_MW_COM_TEST_ALL_SERVICE_ELEMENTS_PROVIDER_H\\n#define SCORE_MW_COM_TEST_ALL_SERVICE_ELEMENTS_PROVIDER_H\\n\\n#include <score/stop_token.hpp>\\n\\nnamespace score::mw::com::test\\n{\\n\\nvoid RunProvider(const score::cpp::stop_token& stop_token);\\n\\n}  // namespace score::mw::com::test\\n\\n#endif  // SCORE_MW_COM_TEST_ALL_SERVICE_ELEMENTS_PROVIDER_H\\n\\n\\nFILE score/mw/com/test/all_service_elements/test_constants.cpp\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n\\n#include \\\"score/mw/com/test/all_service_elements/test_constants.h\\\"\\n\\n\\nFILE score/mw/com/test/all_service_elements/test_constants.h\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n\\n#ifndef SCORE_MW_COM_TEST_ALL_SERVICE_ELEMENTS_TEST_CONSTANTS_H\\n#define SCORE_MW_COM_TEST_ALL_SERVICE_ELEMENTS_TEST_CONSTANTS_H\\n\\n#include \\\"score/mw/com/test/all_service_elements/all_service_elements_datatype.h\\\"\\n#include \\\"score/mw/com/types.h\\\"\\n\\n#include <string>\\n#include <vector>\\n\\nnamespace score::mw::com::test\\n{\\n\\nconst std::string kInterprocessNotificationShmPath{\\\"/all_service_elements_test_interprocess_notification\\\"};\\nconst std::string kFailureMessagePrefix{\\\"all_service_elements\\\"};\\n\\nconst InstanceSpecifier kInstanceSpecifier =\\n    InstanceSpecifier::Create(std::string{\\\"/score/mw/com/test/all_service_elements/all_service_elements_instance\\\"})\\n        .value();\\n\\n// Method test values\\nconst TestType kReturnOnlyMethodReturnValue{15};\\nconst TestType kInArgOnlyMethodTestValueA{17};\\nconst TestType kInArgOnlyMethodTestValueB{18};\\nconst TestType kInArgsAndReturnMethodTestValueA{42};\\nconst TestType kInArgsAndReturnMethodTestValueB{23};\\n\\n// Event test values\\nconst std::vector<TestType> kEvent1ValuesToSend{21U, 22U, 23U};\\nconst std::vector<TestType> kEvent2ValuesToSend{100U, 200U, 300U};\\n\\n// Field initial values, set by the provider before offering the service\\nconst TestType kGetOnlyFieldInitialValue{1};\\nconst TestType kSetAndGetFieldInitialValue{2};\\nconst TestType kGetAndNotifierFieldInitialValue{3};\\nconst TestType kSetAndNotifierFieldInitialValue{4};\\nconst TestType kSetAndGetAndNotifierFieldInitialValue{5};\\nconst TestType kNotifierOnlyFieldInitialValue{6};\\n\\n// Field values to send, set by the provider after offering the service\\nconst std::vector<TestType> kGetAndNotifierFieldValuesToSend{7, 8, 9};\\nconst std::vector<TestType> kSetAndNotifierFieldValuesToSend{10, 11, 12};\\nconst std::vector<TestType> kSetAndGetAndNotifierFieldValuesToSend{13, 14, 15};\\nconst std::vector<TestType> kNotifierOnlyFieldValuesToSend{16, 17, 18};\\n\\nconst std::vector<TestType> kAllGetAndNotifierValues{kGetAndNotifierFieldInitialValue, 7, 8, 9};\\nconst std::vector<TestType> kAllSetAndNotifierValues{kSetAndNotifierFieldInitialValue, 10, 11, 12};\\nconst std::vector<TestType> kAllSetAndGetAndNotifierValues{kSetAndGetAndNotifierFieldInitialValue, 13, 14, 15};\\nconst std::vector<TestType> kAllNotifierOnlyValues{kNotifierOnlyFieldInitialValue, 16, 17, 18};\\n\\n// Value requested by the consumer via Set()\\nconst TestType kSetAndGetRequestValue{51};\\nconst TestType kSetAndNotifierRequestValue{50};\\nconst TestType kSetAndGetAndNotifierRequestValue{52};\\n\\n}  // namespace score::mw::com::test\\n\\n#endif  // SCORE_MW_COM_TEST_ALL_SERVICE_ELEMENTS_TEST_CONSTANTS_H\\n\\n\\nFILE score/mw/com/test/common_test_resources/fail_test.h\\n/********************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License Version 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n ********************************************************************************/\\n#ifndef SCORE_MW_COM_TEST_COMMON_TEST_RESOURCES_FAIL_TEST_H\\n#define SCORE_MW_COM_TEST_COMMON_TEST_RESOURCES_FAIL_TEST_H\\n\\n#include \\\"score/result/error.h\\\"\\n\\n#include <functional>\\n#include <sstream>\\n#include <utility>\\n\\nnamespace score::mw::com::test\\n{\\n\\nnamespace detail\\n{\\n\\nvoid FailTest(std::stringstream&& strstr);\\n\\ntemplate <typename Start, typename... Tail>\\nvoid FailTest(std::stringstream&& strstr, Start&& start, Tail&&... tail)\\n{\\n    // Since score::result::Error does not have an operator<< overload for a stringstream and no method to convert it to\\n    // a string, we manually stringify it here.\\n    if constexpr (std::is_same_v<std::decay_t<Start>, score::result::Error>)\\n    {\\n        strstr << start.Message() << \\\" / \\\" << start.UserMessage();\\n    }\\n    else\\n    {\\n        strstr << std::forward<Start>(start);\\n    }\\n\\n    if constexpr (sizeof...(Tail) > 0U)\\n    {\\n        FailTest(std::move(strstr), std::forward<Tail>(tail)...);\\n    }\\n    else\\n    {\\n        FailTest(std::move(strstr));\\n    }\\n}\\n\\n}  // namespace detail\\n\\n/// \\\\brief RAII guard to set a test exit function that will be called when FailTest is invoked or when the guard is\\n/// destroyed.\\nclass ExitFunctionGuard\\n{\\n  public:\\n    using ExitFunction = std::function<void()>;\\n\\n    explicit ExitFunctionGuard(ExitFunction exit_function);\\n    ~ExitFunctionGuard();\\n\\n    ExitFunctionGuard(const ExitFunctionGuard&) = delete;\\n    ExitFunctionGuard& operator=(const ExitFunctionGuard&) = delete;\\n    ExitFunctionGuard(ExitFunctionGuard&&) = delete;\\n    ExitFunctionGuard& operator=(ExitFunctionGuard&&) = delete;\\n};\\n\\n/// \\\\brief Fail a test by exiting the program with EXIT_FAILURE and printing a message to stderr.\\n/// \\\\param args variadic number of arguments, each one must be streamable to a standard stringstream.\\ntemplate <typename... Args>\\nvoid FailTest(Args&&... args)\\n{\\n    std::stringstream strstr;\\n    strstr << \\\"\\\\033[1m\\\\033[31m\\\";\\n    detail::FailTest(std::move(strstr), std::forward<Args>(args)...);\\n}\\n\\n}  // namespace score::mw::com::test\\n\\n#endif  // SCORE_MW_COM_TEST_COMMON_TEST_RESOURCES_FAIL_TEST_H\\n\\n\\nFILE score/mw/com/test/common_test_resources/proxy_observer.h\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License Version 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n\\n#include \\\"score/concurrency/future/interruptible_promise.h\\\"\\n#include \\\"score/mw/com/com_error_domain.h\\\"\\n#include \\\"score/mw/com/types.h\\\"\\n\\n#include <fstream>\\n#include <iostream>\\n#include <memory>\\n#include <optional>\\n#include <unordered_map>\\n#include <utility>\\n\\nnamespace score::mw::com::test\\n{\\n\\nnamespace\\n{\\ntemplate <typename Proxy>\\nclass ProxyObserver\\n{\\n  public:\\n    ProxyObserver(std::string_view instance_Specifier)\\n        : instance_specifier_result_{InstanceSpecifier::Create(std::string{instance_Specifier})}\\n    {\\n        if (!instance_specifier_result_.has_value())\\n        {\\n            std::cerr << \\\"Unable to create instance specifier\\\\n\\\";\\n        }\\n    }\\n\\n    ~ProxyObserver()\\n    {\\n        if (handle_.has_value())\\n        {\\n            std::ignore = Proxy::StopFindService(handle_.value());\\n        }\\n    }\\n\\n    Result<FindServiceHandle> StartServiceDiscovery(std::size_t required_number_of_services) noexcept\\n    {\\n        auto callback = [this, required_number_of_services](auto service_handle_container,\\n                                                            auto find_service_handle) noexcept {\\n            std::cout << \\\"handler called\\\" << std::endl;\\n            for (auto& handle : service_handle_container)\\n            {\\n                auto lola_proxy_result = Proxy::Create(handle);\\n                if (lola_proxy_result.has_value())\\n                {\\n                    std::cout << \\\"successfully created lola proxy\\\" << std::endl;\\n                    proxies_.insert({handle, std::move(lola_proxy_result.value())});\\n                }\\n                else\\n                {\\n                    std::cerr << \\\"unable to create lola proxy:\\\" << lola_proxy_result.error().Message() << std::endl;\\n                }\\n            }\\n            if (proxies_.size() == required_number_of_services)\\n            {\\n                std::cout << \\\"Requested number of proxies created\\\" << std::endl;\\n                promise_.SetValue();\\n                score::cpp::ignore = Proxy::StopFindService(find_service_handle);\\n            }\\n        };\\n\\n        handle_ = Proxy::StartFindService(callback, instance_specifier_result_.value());\\n        return handle_;\\n    }\\n\\n    std::int32_t CheckProxyCreation(const score::cpp::stop_token& stop_token) noexcept\\n    {\\n        auto future = promise_.GetInterruptibleFuture().value();\\n        auto future_status = future.Wait(stop_token);\\n        if (!future_status.has_value())\\n        {\\n            std::cerr << \\\"Could not find the requested number of services\\\" << std::endl;\\n            return EXIT_FAILURE;\\n        }\\n\\n        return EXIT_SUCCESS;\\n    }\\n\\n  private:\\n    score::Result<score::mw::com::InstanceSpecifier> instance_specifier_result_;\\n    std::unordered_map<typename Proxy::HandleType, Proxy> proxies_{};\\n    concurrency::InterruptiblePromise<void> promise_{};\\n    // handle has deleted default constructor\\n    Result<FindServiceHandle> handle_ = MakeUnexpected(score::mw::com::ComErrc::kUnsetFailure);\\n};\\n\\n}  // namespace\\n\\n}  // namespace score::mw::com::test\\n\\n\\nFILE score/mw/com/test/common_test_resources/sctf_test_runner.h\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License Version 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n\\n#ifndef SCORE_MW_COM_TEST_COMMON_TEST_RESOURCES_SCTF_TEST_RUNNER_H\\n#define SCORE_MW_COM_TEST_COMMON_TEST_RESOURCES_SCTF_TEST_RUNNER_H\\n\\n#include <score/stop_token.hpp>\\n#include <optional>\\n\\n#include <algorithm>\\n#include <chrono>\\n#include <future>\\n#include <string>\\n#include <vector>\\n\\nnamespace score::mw::com::test\\n{\\n\\nclass SctfTestRunner\\n{\\n  public:\\n    class RunParameters\\n    {\\n      public:\\n        enum class Parameters\\n        {\\n            CYCLE_TIME,\\n            MODE,\\n            NUM_CYCLES,\\n            SERVICE_INSTANCE_MANIFEST,\\n            UID,\\n            NUM_RETRIES,\\n            RETRY_BACKOFF_TIME,\\n            SHOULD_MODIFY_DATA_SEGMENT,\\n        };\\n\\n        RunParameters(const std::vector<RunParameters::Parameters>& allowed_parameters,\\n                      std::optional<std::chrono::milliseconds> cycle_time,\\n                      std::optional<std::string> mode,\\n                      std::optional<std::size_t> num_cycles,\\n                      std::optional<std::string> service_instance_manifest,\\n                      std::optional<uid_t> uid,\\n                      std::optional<std::size_t> num_retries,\\n                      std::optional<std::chrono::milliseconds> retry_backoff_time,\\n                      std::optional<bool> should_modify_data_segment) noexcept;\\n\\n        std::chrono::milliseconds GetCycleTime() const;\\n        std::string GetMode() const;\\n        std::size_t GetNumCycles() const;\\n        std::string GetServiceInstanceManifest() const;\\n        uid_t GetUid() const;\\n        std::size_t GetNumRetries() const;\\n        std::chrono::milliseconds GetRetryBackoffTime() const;\\n        bool GetShouldModifyDataSegment() const;\\n\\n        std::optional<std::chrono::milliseconds> GetOptionalCycleTime() const;\\n        std::optional<std::string> GetOptionalMode() const;\\n        std::optional<std::size_t> GetOptionalNumCycles() const;\\n        std::optional<std::string> GetOptionalServiceInstanceManifest() const;\\n        std::optional<uid_t> GetOptionalUid() const;\\n        std::optional<std::size_t> GetOptionalNumRetries() const;\\n        std::optional<std::chrono::milliseconds> GetOptionalRetryBackoffTime() const;\\n\\n      private:\\n        const std::vector<RunParameters::Parameters> allowed_parameters_;\\n        const std::optional<std::chrono::milliseconds> cycle_time_;\\n        const std::optional<std::string> mode_;\\n        const std::optional<std::size_t> num_cycles_;\\n        const std::optional<std::string> service_instance_manifest_;\\n        const std::optional<uid_t> uid_;\\n        const std::optional<std::size_t> num_retries_;\\n        const std::optional<std::chrono::milliseconds> retry_backoff_time_;\\n        const std::optional<bool> should_modify_data_segment_;\\n    };\\n\\n    SctfTestRunner(int argc, const char** argv, const std::vector<RunParameters::Parameters>& allowed_parameters);\\n\\n    score::cpp::stop_token GetStopToken() const noexcept\\n    {\\n        return stop_source_.get_token();\\n    }\\n    score::cpp::stop_source GetStopSource() noexcept\\n    {\\n        return stop_source_;\\n    }\\n    RunParameters GetRunParameters() const noexcept\\n    {\\n        return run_parameters_;\\n    }\\n\\n    static int WaitForAsyncTestResults(std::vector<std::future<int>>& future_return_values);\\n\\n  private:\\n    RunParameters ParseCommandLineArguments(int argc,\\n                                            const char** argv,\\n                                            const std::vector<RunParameters::Parameters>& allowed_parameters) const;\\n    void SetupSigTermHandler();\\n\\n    const RunParameters run_parameters_;\\n    score::cpp::stop_source stop_source_;\\n};\\n\\n}  // namespace score::mw::com::test\\n\\n#endif  // SCORE_MW_COM_TEST_COMMON_TEST_RESOURCES_SCTF_TEST_RUNNER_H\\n\\n\\nFILE score/mw/com/test/common_test_resources/test_interface.h\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License Version 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n\\n#ifndef SCORE_MW_COM_TEST_COMMON_TEST_RESOURCES_TEST_INTERFACE_H\\n#define SCORE_MW_COM_TEST_COMMON_TEST_RESOURCES_TEST_INTERFACE_H\\n\\n#include \\\"score/mw/com/types.h\\\"\\n\\n#include <cstdint>\\n#include <vector>\\n\\nnamespace score::mw::com::test\\n{\\n\\ntemplate <typename T>\\nclass TestInterface : public T::Base\\n{\\n  public:\\n    using T::Base::Base;\\n\\n    // Only WithNotifier is needed since the proxy subscribes to receive the initial value the skeleton\\n    // publishes via Update(). No Get/Set so, WithGetter and WithSetter must stay absent until we add tests that require\\n    // them.\\n    typename T::template Field<std::int32_t, score::mw::com::WithNotifier> test_field{*this, \\\"test_field\\\"};\\n};\\n\\n}  // namespace score::mw::com::test\\n\\n#endif  // SCORE_MW_COM_TEST_COMMON_TEST_RESOURCES_TEST_INTERFACE_H\\n\\n\\nFILE score/mw/com/test/pkg_application.bzl\\n# *******************************************************************************\\n# Copyright (c) 2026 Contributors to the Eclipse Foundation\\n#\\n# See the NOTICE file(s) distributed with this work for additional\\n# information regarding copyright ownership.\\n#\\n# This program and the accompanying materials are made available under the\\n# terms of the Apache License Version 2.0 which is available at\\n# https://www.apache.org/licenses/LICENSE-2.0\\n#\\n# SPDX-License-Identifier: Apache-2.0\\n# *******************************************************************************\\n\\n\\\"\\\"\\\"Macro packaging an application together with its configuration files.\\\"\\\"\\\"\\n\\nload(\\\"@rules_pkg//pkg:mappings.bzl\\\", \\\"pkg_attributes\\\", \\\"pkg_filegroup\\\", \\\"pkg_files\\\")\\n\\nvisibility([\\\"//...\\\"])\\n\\ndef pkg_application(name, app_name, bin = [], etc = [], etc_deps = [], **kwargs):\\n    pkg_files(\\n        name = \\\"{}_binary\\\".format(name),\\n        srcs = bin,\\n        prefix = \\\"/opt/{}/bin\\\".format(app_name),\\n        attributes = pkg_attributes(\\n            mode = \\\"0777\\\",\\n        ),\\n        **kwargs\\n    )\\n\\n    pkg_files(\\n        name = \\\"{}_etc_files\\\".format(name),\\n        srcs = etc,\\n        **kwargs\\n    )\\n\\n    pkg_filegroup(\\n        name = \\\"{}_etc\\\".format(name),\\n        srcs = [\\n            \\\"{}_etc_files\\\".format(name),\\n        ] + etc_deps,\\n        prefix = \\\"/opt/{}/etc\\\".format(app_name),\\n    )\\n\\n    pkg_filegroup(\\n        name = name,\\n        srcs = [\\n            \\\"{}_binary\\\".format(name),\\n            \\\"{}_etc\\\".format(name),\\n        ],\\n        prefix = \\\"/\\\",\\n        **kwargs\\n    )\\n\\n\\nFILE score/mw/com/test/service_discovery_offer_and_search/BUILD\\n# *******************************************************************************\\n# Copyright (c) 2026 Contributors to the Eclipse Foundation\\n#\\n# See the NOTICE file(s) distributed with this work for additional\\n# information regarding copyright ownership.\\n#\\n# This program and the accompanying materials are made available under the\\n# terms of the Apache License Version 2.0 which is available at\\n# https://www.apache.org/licenses/LICENSE-2.0\\n#\\n# SPDX-License-Identifier: Apache-2.0\\n# *******************************************************************************\\n\\nload(\\\"@rules_cc//cc:defs.bzl\\\", \\\"cc_binary\\\", \\\"cc_library\\\")\\nload(\\\"@score_baselibs//score/language/safecpp:toolchain_features.bzl\\\", \\\"COMPILER_WARNING_FEATURES\\\")\\nload(\\\"//bazel/tools:json_schema_validator.bzl\\\", \\\"validate_json_schema_test\\\")\\nload(\\\"//score/mw/com/test:pkg_application.bzl\\\", \\\"pkg_application\\\")\\n\\nvalidate_json_schema_test(\\n    name = \\\"validate_lola_service_schema\\\",\\n    json = \\\"config/service/mw_com_config.json\\\",\\n    schema = \\\"//score/mw/com:config_schema\\\",\\n    tags = [\\\"lint\\\"],\\n)\\n\\nvalidate_json_schema_test(\\n    name = \\\"validate_lola_client_schema\\\",\\n    json = \\\"config/client/mw_com_config.json\\\",\\n    schema = \\\"//score/mw/com:config_schema\\\",\\n    tags = [\\\"lint\\\"],\\n)\\n\\ncc_library(\\n    name = \\\"test_datatype\\\",\\n    srcs = [\\\"test_datatype.cpp\\\"],\\n    hdrs = [\\\"test_datatype.h\\\"],\\n    features = COMPILER_WARNING_FEATURES,\\n    deps = [\\n        \\\"//score/mw/com\\\",\\n        \\\"//score/mw/com/test/common_test_resources:test_interface\\\",\\n    ],\\n)\\n\\ncc_binary(\\n    name = \\\"service\\\",\\n    srcs = [\\\"service.cpp\\\"],\\n    data = [\\\"config/service/mw_com_config.json\\\"],\\n    features = COMPILER_WARNING_FEATURES + [\\n        \\\"aborts_upon_exception\\\",\\n    ],\\n    deps = [\\n        \\\":test_datatype\\\",\\n        \\\"//score/mw/com\\\",\\n        \\\"//score/mw/com/test/common_test_resources:common_service\\\",\\n        \\\"//score/mw/com/test/common_test_resources:sctf_test_runner\\\",\\n        \\\"//score/mw/com/test/common_test_resources:sync_utils\\\",\\n        \\\"@score_baselibs//score/mw/log\\\",\\n        \\\"@score_baselibs//score/result\\\",\\n    ],\\n)\\n\\ncc_binary(\\n    name = \\\"client\\\",\\n    srcs = [\\\"client.cpp\\\"],\\n    data = [\\\"config/client/mw_com_config.json\\\"],\\n    features = COMPILER_WARNING_FEATURES + [\\n        \\\"aborts_upon_exception\\\",\\n    ],\\n    deps = [\\n        \\\":test_datatype\\\",\\n        \\\"//score/mw/com\\\",\\n        \\\"//score/mw/com:runtime\\\",\\n        \\\"//score/mw/com/test/common_test_resources:proxy_observer\\\",\\n        \\\"//score/mw/com/test/common_test_resources:sctf_test_runner\\\",\\n        \\\"//score/mw/com/test/common_test_resources:sync_utils\\\",\\n        \\\"@score_baselibs//score/mw/log\\\",\\n    ],\\n)\\n\\npkg_application(\\n    name = \\\"service-pkg\\\",\\n    app_name = \\\"ServiceApp\\\",\\n    bin = [\\\":service\\\"],\\n    etc = [\\n        \\\"config/service/mw_com_config.json\\\",\\n        \\\"config/logging.json\\\",\\n    ],\\n    visibility = [\\n        \\\"//platform/aas/test/mw/com:__pkg__\\\",\\n        \\\"//score/mw/com/test:__pkg__\\\",\\n        \\\"//score/mw/com/test/service_discovery_offer_and_search:__subpackages__\\\",\\n    ],\\n)\\n\\npkg_application(\\n    name = \\\"client-pkg\\\",\\n    app_name = \\\"ClientApp\\\",\\n    bin = [\\\":client\\\"],\\n    etc = [\\n        \\\"config/client/mw_com_config.json\\\",\\n        \\\"config/logging.json\\\",\\n    ],\\n    visibility = [\\n        \\\"//platform/aas/test/mw/com:__pkg__\\\",\\n        \\\"//score/mw/com/test:__pkg__\\\",\\n        \\\"//score/mw/com/test/service_discovery_offer_and_search:__subpackages__\\\",\\n    ],\\n)\\n\\n\\nFILE score/mw/com/test/service_discovery_offer_and_search/client.cpp\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License Version 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n\\n#include \\\"score/concurrency/future/interruptible_promise.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/proxy_observer.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/sctf_test_runner.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/sync_utils.h\\\"\\n#include \\\"score/mw/com/test/service_discovery_offer_and_search/test_datatype.h\\\"\\n#include \\\"score/mw/com/types.h\\\"\\n\\n#include <fstream>\\n#include <iostream>\\n#include <utility>\\n#include <vector>\\n\\nnamespace score::mw::com::test\\n{\\n\\nnamespace\\n{\\n\\nint run_client(const score::cpp::stop_token& stop_token)\\n{\\n    using score::mw::com::test::TestDataProxy;\\n\\n    score::mw::com::test::SyncCoordinator sync_coordinator(std::string{kFileName});\\n    // waiting for Service to offer service then start searching\\n    sync_coordinator.Wait(stop_token);\\n\\n    ProxyObserver<TestDataProxy> proxy_observer(kInstanceSpecifierStringClient);\\n    const auto find_service_handle_result = proxy_observer.StartServiceDiscovery(kNumberOfOfferedServices);\\n    if (!find_service_handle_result.has_value())\\n    {\\n        std::cerr << \\\"unable to start service discovery\\\" << find_service_handle_result.error().Message() << std::endl;\\n    }\\n    return proxy_observer.CheckProxyCreation(stop_token);\\n}\\n\\n}  // namespace\\n\\n}  // namespace score::mw::com::test\\n\\nint main(int argc, const char** argv)\\n{\\n    score::mw::com::test::SctfTestRunner test_runner(argc, argv, {});\\n\\n    const auto stop_token = test_runner.GetStopToken();\\n\\n    score::mw::com::test::run_client(stop_token);\\n    score::mw::com::test::SyncCoordinator::CleanUp(std::string{score::mw::com::test::kFileName});\\n\\n    return 0;\\n}\\n\\n\\nFILE score/mw/com/test/service_discovery_offer_and_search/config/client/mw_com_config.json\\n{\\n  \\\"serviceTypes\\\": [\\n    {\\n      \\\"serviceTypeName\\\": \\\"/score/mw/com/test/service_discovery_offer_and_search\\\",\\n      \\\"version\\\": {\\n        \\\"major\\\": 1,\\n        \\\"minor\\\": 0\\n      },\\n      \\\"bindings\\\": [\\n        {\\n          \\\"binding\\\": \\\"SHM\\\",\\n          \\\"serviceId\\\": 3428,\\n          \\\"fields\\\": [\\n            {\\n              \\\"fieldName\\\": \\\"test_field\\\",\\n              \\\"fieldId\\\": 1\\n            }\\n          ]\\n        }\\n      ]\\n    }\\n  ],\\n  \\\"serviceInstances\\\": [\\n    {\\n      \\\"instanceSpecifier\\\": \\\"test/service_discovery_offer_and_search_client\\\",\\n      \\\"serviceTypeName\\\": \\\"/score/mw/com/test/service_discovery_offer_and_search\\\",\\n      \\\"version\\\": {\\n        \\\"major\\\": 1,\\n        \\\"minor\\\": 0\\n      },\\n      \\\"instances\\\": [\\n        {\\n          \\\"asil-level\\\": \\\"QM\\\",\\n          \\\"binding\\\": \\\"SHM\\\",\\n          \\\"fields\\\": [\\n            {\\n              \\\"fieldName\\\": \\\"test_field\\\",\\n              \\\"useGetIfAvailable\\\": false,\\n              \\\"useSetIfAvailable\\\": false\\n            }\\n          ]\\n        }\\n      ]\\n    }\\n  ]\\n}\\n\\n\\n\\nFILE score/mw/com/test/service_discovery_offer_and_search/config/logging.json\\n{\\n  \\\"appId\\\": \\\"SDOS\\\",\\n  \\\"appDesc\\\": \\\"test_service_discovery_offer_search\\\",\\n  \\\"logLevel\\\": \\\"kDebug\\\",\\n  \\\"logLevelThresholdConsole\\\": \\\"kDebug\\\",\\n  \\\"logMode\\\": \\\"kRemote|kConsole\\\"\\n}\\n\\n\\n\\nFILE score/mw/com/test/service_discovery_offer_and_search/config/service/mw_com_config.json\\n{\\n  \\\"serviceTypes\\\": [\\n    {\\n      \\\"serviceTypeName\\\": \\\"/score/mw/com/test/service_discovery_offer_and_search\\\",\\n      \\\"version\\\": {\\n        \\\"major\\\": 1,\\n        \\\"minor\\\": 0\\n      },\\n      \\\"bindings\\\": [\\n        {\\n          \\\"binding\\\": \\\"SHM\\\",\\n          \\\"serviceId\\\": 3428,\\n          \\\"fields\\\": [\\n            {\\n              \\\"fieldName\\\": \\\"test_field\\\",\\n              \\\"fieldId\\\": 1\\n            }\\n          ]\\n        }\\n      ]\\n    }\\n  ],\\n  \\\"serviceInstances\\\": [\\n    {\\n      \\\"instanceSpecifier\\\": \\\"test/service_discovery_offer_and_search_service_first\\\",\\n      \\\"serviceTypeName\\\": \\\"/score/mw/com/test/service_discovery_offer_and_search\\\",\\n      \\\"version\\\": {\\n        \\\"major\\\": 1,\\n        \\\"minor\\\": 0\\n      },\\n      \\\"instances\\\": [\\n        {\\n          \\\"instanceId\\\": 1024,\\n          \\\"asil-level\\\": \\\"QM\\\",\\n          \\\"binding\\\": \\\"SHM\\\",\\n          \\\"fields\\\": [\\n            {\\n              \\\"fieldName\\\": \\\"test_field\\\",\\n              \\\"maxSubscribers\\\": 1,\\n              \\\"numberOfSampleSlots\\\": 1\\n            }\\n          ]\\n        }\\n      ]\\n    },\\n    {\\n      \\\"instanceSpecifier\\\": \\\"test/service_discovery_offer_and_search_service_second\\\",\\n      \\\"serviceTypeName\\\": \\\"/score/mw/com/test/service_discovery_offer_and_search\\\",\\n      \\\"version\\\": {\\n        \\\"major\\\": 1,\\n        \\\"minor\\\": 0\\n      },\\n      \\\"instances\\\": [\\n        {\\n          \\\"instanceId\\\": 1025,\\n          \\\"asil-level\\\": \\\"QM\\\",\\n          \\\"binding\\\": \\\"SHM\\\",\\n          \\\"fields\\\": [\\n            {\\n              \\\"fieldName\\\": \\\"test_field\\\",\\n              \\\"maxSubscribers\\\": 1,\\n              \\\"numberOfSampleSlots\\\": 1\\n            }\\n          ]\\n        }\\n      ]\\n    }\\n  ]\\n}\\n\\n\\n\\nFILE score/mw/com/test/service_discovery_offer_and_search/integration_test/BUILD\\n# *******************************************************************************\\n# Copyright (c) 2026 Contributors to the Eclipse Foundation\\n#\\n# See the NOTICE file(s) distributed with this work for additional\\n# information regarding copyright ownership.\\n#\\n# This program and the accompanying materials are made available under the\\n# terms of the Apache License Version 2.0 which is available at\\n# https://www.apache.org/licenses/LICENSE-2.0\\n#\\n# SPDX-License-Identifier: Apache-2.0\\n# *******************************************************************************\\n\\nload(\\\"@rules_pkg//pkg:mappings.bzl\\\", \\\"pkg_filegroup\\\")\\nload(\\\"//quality/integration_testing:integration_testing.bzl\\\", \\\"integration_test\\\")\\n\\npkg_filegroup(\\n    name = \\\"filesystem\\\",\\n    srcs = [\\n        \\\"//score/mw/com/test/service_discovery_offer_and_search:client-pkg\\\",\\n        \\\"//score/mw/com/test/service_discovery_offer_and_search:service-pkg\\\",\\n    ],\\n)\\n\\nintegration_test(\\n    name = \\\"test_service_discovery_offer_and_search\\\",\\n    timeout = \\\"moderate\\\",\\n    srcs = [\\\"test_service_discovery_offer_and_search.py\\\"],\\n    filesystem = \\\":filesystem\\\",\\n)\\n\\n\\nFILE score/mw/com/test/service_discovery_offer_and_search/integration_test/test_service_discovery_offer_and_search.py\\n# *******************************************************************************\\n# Copyright (c) 2026 Contributors to the Eclipse Foundation\\n#\\n# See the NOTICE file(s) distributed with this work for additional\\n# information regarding copyright ownership.\\n#\\n# This program and the accompanying materials are made available under the\\n# terms of the Apache License Version 2.0 which is available at\\n# https://www.apache.org/licenses/LICENSE-2.0\\n#\\n# SPDX-License-Identifier: Apache-2.0\\n# *******************************************************************************\\n\\n\\\"\\\"\\\"Integration tests for service discovery offer and search.\\\"\\\"\\\"\\n\\n\\ndef client(target):\\n    args = []\\n    return target.wrap_exec(\\\"bin/client\\\", args, cwd=\\\"/opt/ClientApp\\\", wait_on_exit=True)\\n\\n\\ndef service(target):\\n    args = [\\\"--cycle-time\\\", \\\"250\\\"]\\n    return target.wrap_exec(\\\"bin/service\\\", args, cwd=\\\"/opt/ServiceApp\\\")\\n\\n\\ndef test_service_discovery_offer_and_search(target):\\n    \\\"\\\"\\\"Test service discovery where service offers first, then client searches.\\n\\n    The service also issues a second OfferService() call on the first\\n    service instance to verify that offering an already-offered service is\\n    handled without affecting the already-offered instance or the client's\\n    ability to discover it.\\n    \\\"\\\"\\\"\\n    with service(target), client(target):\\n        pass\\n\\n\\nFILE score/mw/com/test/service_discovery_offer_and_search/service.cpp\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License Version 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n\\n#include \\\"score/concurrency/future/interruptible_future.h\\\"\\n#include \\\"score/concurrency/future/interruptible_promise.h\\\"\\n#include \\\"score/mw/com/com_error_domain.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/common_service.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/sctf_test_runner.h\\\"\\n#include \\\"score/mw/com/test/common_test_resources/sync_utils.h\\\"\\n\\n#include \\\"score/mw/com/test/service_discovery_offer_and_search/test_datatype.h\\\"\\n\\n#include \\\"score/result/error.h\\\"\\n#include \\\"score/result/result.h\\\"\\n\\n#include <score/stop_token.hpp>\\n\\n#include <chrono>\\n#include <fstream>\\n#include <iostream>\\n#include <thread>\\n#include <utility>\\n\\nnamespace score::mw::com::test\\n{\\n\\nusing namespace std::chrono_literals;\\n\\nnamespace\\n{\\nint run_service(const std::chrono::milliseconds& cycle_time, const score::cpp::stop_token& stop_token)\\n{\\n    auto first_service_result = Service<TestDataSkeleton>::Create(kInstanceSpecifierStringServiceFirst);\\n    if (!first_service_result.has_value())\\n    {\\n        std::cerr << first_service_result.error().Message() << std::endl;\\n        return 1;\\n    }\\n    const auto first_offer_service_result = first_service_result.value().OfferService(kTestValue);\\n    if (!first_offer_service_result.has_value())\\n    {\\n        std::cerr << \\\"Could not offer first service, terminating\\\\n\\\";\\n        return 3;\\n    }\\n\\n    // Offering the same service a second time must not cause any issues (e.g. crashing or corrupting the\\n    // already-offered service) and the call should simply return successfully.\\n    // TODO: Should be moved into dedicated integration test\\n    // (https://github.com/eclipse-score/communication/issues/1167)\\n    const auto duplicate_offer_service_result = first_service_result.value().OfferService(kTestValue);\\n    if (!duplicate_offer_service_result.has_value())\\n    {\\n        std::cerr << \\\"Second OfferService() call unexpectedly failed, terminating\\\\n\\\";\\n        return 4;\\n    }\\n\\n    auto second_service_result = Service<TestDataSkeleton>::Create(kInstanceSpecifierStringServiceSecond);\\n    if (!second_service_result.has_value())\\n    {\\n        std::cerr << second_service_result.error().Message() << std::endl;\\n        return 2;\\n    }\\n    const auto second_offer_service_result = second_service_result.value().OfferService(kTestValue);\\n    if (!second_offer_service_result.has_value())\\n    {\\n        std::cerr << \\\"Could not offer second service, terminating\\\\n\\\";\\n        return 3;\\n    }\\n\\n    // Offer Service first then Sync. with Client to start searching for service\\n    score::mw::com::test::SyncCoordinator sync_coordinator(std::string{kFileName});\\n    sync_coordinator.Signal();\\n    std::cout << \\\"Sending Sync. Signal to Client\\\" << std::endl;\\n\\n    while (!stop_token.stop_requested())\\n    {\\n        std::this_thread::sleep_for(cycle_time);\\n    }\\n\\n    return 0;\\n}\\n}  // namespace\\n\\n}  // namespace score::mw::com::test\\n\\nint main(int argc, const char** argv)\\n{\\n    using Parameters = score::mw::com::test::SctfTestRunner::RunParameters::Parameters;\\n\\n    const std::vector<Parameters> allowed_parameters{Parameters::CYCLE_TIME};\\n    score::mw::com::test::SctfTestRunner test_runner(argc, argv, allowed_parameters);\\n    const auto& run_parameters = test_runner.GetRunParameters();\\n    const auto cycle_time = run_parameters.GetCycleTime();\\n    const auto stop_token = test_runner.GetStopToken();\\n\\n    return score::mw::com::test::run_service(cycle_time, stop_token);\\n}\\n\\n\\nFILE score/mw/com/test/service_discovery_offer_and_search/test_datatype.cpp\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License Version 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n\\n#include \\\"score/mw/com/test/service_discovery_offer_and_search/test_datatype.h\\\"\\n\\n\\nFILE score/mw/com/test/service_discovery_offer_and_search/test_datatype.h\\n/*******************************************************************************\\n * Copyright (c) 2026 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License Version 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n *******************************************************************************/\\n\\n#ifndef SCORE_MW_COM_TEST_SERVICE_DISCOVERY_OFFER_AND_SEARCH_TEST_DATATYPE_H\\n#define SCORE_MW_COM_TEST_SERVICE_DISCOVERY_OFFER_AND_SEARCH_TEST_DATATYPE_H\\n\\n#include \\\"score/mw/com/test/common_test_resources/test_interface.h\\\"\\n#include \\\"score/mw/com/types.h\\\"\\n\\n#include <cstdint>\\n#include <vector>\\n\\nnamespace score::mw::com::test\\n{\\nconstexpr std::string_view kFileName = \\\"/tmp/service_discovery_offer_and_search.txt\\\";\\nconstexpr std::string_view kInstanceSpecifierStringClient = \\\"test/service_discovery_offer_and_search_client\\\";\\nconstexpr std::string_view kInstanceSpecifierStringServiceFirst =\\n    \\\"test/service_discovery_offer_and_search_service_first\\\";\\nconstexpr std::string_view kInstanceSpecifierStringServiceSecond =\\n    \\\"test/service_discovery_offer_and_search_service_second\\\";\\nconst std::int32_t kNumberOfOfferedServices = 2;\\nconst std::int32_t kTestValue = 986;\\n\\nusing TestDataProxy = score::mw::com::AsProxy<TestInterface>;\\nusing TestDataSkeleton = score::mw::com::AsSkeleton<TestInterface>;\\n\\n}  // namespace score::mw::com::test\\n\\n#endif  // SCORE_MW_COM_TEST_SERVICE_DISCOVERY_OFFER_AND_SEARCH_TEST_DATATYPE_H\\n\\n\\nFILE score/mw/com/types.h\\n/********************************************************************************\\n * Copyright (c) 2025 Contributors to the Eclipse Foundation\\n *\\n * See the NOTICE file(s) distributed with this work for additional\\n * information regarding copyright ownership.\\n *\\n * This program and the accompanying materials are made available under the\\n * terms of the Apache License Version 2.0 which is available at\\n * https://www.apache.org/licenses/LICENSE-2.0\\n *\\n * SPDX-License-Identifier: Apache-2.0\\n ********************************************************************************/\\n#ifndef SCORE_MW_COM_TYPES_H\\n#define SCORE_MW_COM_TYPES_H\\n\\n#include \\\"score/mw/com/impl/methods/method_signature_element_ptr.h\\\"\\n#include \\\"score/mw/com/impl/plumbing/sample_allocatee_ptr.h\\\"\\n#include \\\"score/mw/com/impl/plumbing/sample_ptr.h\\\"\\n\\n#include \\\"score/mw/com/impl/event_receive_handler.h\\\"\\n#include \\\"score/mw/com/impl/field_tags.h\\\"\\n#include \\\"score/mw/com/impl/find_service_handle.h\\\"\\n#include \\\"score/mw/com/impl/find_service_handler.h\\\"\\n#include \\\"score/mw/com/impl/generic_proxy.h\\\"\\n#include \\\"score/mw/com/impl/generic_proxy_event.h\\\"\\n#include \\\"score/mw/com/impl/generic_skeleton.h\\\"\\n#include \\\"score/mw/com/impl/generic_skeleton_event.h\\\"\\n#include \\\"score/mw/com/impl/handle_type.h\\\"\\n#include \\\"score/mw/com/impl/instance_identifier.h\\\"\\n#include \\\"score/mw/com/impl/instance_specifier.h\\\"\\n#include \\\"score/mw/com/impl/receive_handler_registration_changed_handler.h\\\"\\n#include \\\"score/mw/com/impl/skeleton_base.h\\\"\\n#include \\\"score/mw/com/impl/subscription_state.h\\\"\\n#include \\\"score/mw/com/impl/traits.h\\\"\\n\\n#include <vector>\\n/// \\\\api\\n/// \\\\brief The Types header file includes the data type definitions which are specific for the\\n/// mw::com API.\\n/// \\\\requirement SWS_CM_01018, SWS_CM_01013\\n\\nnamespace score::mw::com\\n{\\n/// \\\\api\\n/// \\\\brief Represents a specific instance of a service.\\n/// \\\\requirement SWS_CM_01019\\nusing InstanceIdentifier = ::score::mw::com::impl::InstanceIdentifier;\\n\\n/// \\\\api\\n/// \\\\brief Identifier for an application port. Maps design to deployment.\\n/// \\\\requirement SWS_CM_00350\\nusing InstanceSpecifier = ::score::mw::com::impl::InstanceSpecifier;\\n\\n/// \\\\api\\n/// \\\\brief The container holds a list of instance identifiers and is used as\\n/// a return value of the ResolveInstanceIDs method.\\n/// \\\\requirement SWS_CM_00319\\nusing InstanceIdentifierContainer = std::vector<InstanceIdentifier>;\\n\\n/// \\\\api\\n/// \\\\brief Handle for service discovery operations.\\n/// See StartFindService() and StopFindService() for more information.\\nusing FindServiceHandle = ::score::mw::com::impl::FindServiceHandle;\\n\\n/// \\\\api\\n/// \\\\brief Handle to a service instance.\\nusing HandleType = ::score::mw::com::impl::HandleType;\\n\\n/// \\\\api\\n/// \\\\brief Container with handles representing currently available service instances.\\n/// See StartFindService() for more information.\\ntemplate <typename T>\\nusing ServiceHandleContainer = ::score::mw::com::impl::ServiceHandleContainer<T>;\\n\\n/// \\\\api\\n/// \\\\brief Callback that notifies the callee about service availability changes.\\n/// See ProxyBase::StartFindService for more information.\\ntemplate <typename T>\\nusing FindServiceHandler = ::score::mw::com::impl::FindServiceHandler<T>;\\n\\n/// \\\\api\\n/// \\\\brief Subscription state of a proxy event.\\n/// See ProxyEvent::GetSubscriptionStatus for slightly more information.\\nusing SubscriptionState = ::score::mw::com::impl::SubscriptionState;\\n\\n/// Carries the received data on proxy side\\ntemplate <typename SampleType>\\nusing Sample